{
  "name": "Veritas: Multi-Agent Reasoning",
  "description": "A collaborative multi-agent system dedicated to radical truth. Three AI agents (Analyst, Skeptic, Judge) debate to ensure factual accuracy and eliminate hallucinations."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface AgentConfig {
  role: 'analyst' | 'skeptic' | 'judge';
  name: string;
  color: string;
  style: string;
  task: string;
  icon: string;
}

export interface SystemConfig {
  global_rules: string;
  agents: AgentConfig[];
}

export interface LogEntry {
  id: string;
  agentRole: 'analyst' | 'skeptic' | 'judge';
  agentName: string;
  content: string;
  timestamp: number;
  isThinking?: boolean;
}

export interface ReasoningResult {
  finalAnswer: string;
  logs: LogEntry[];
  success: boolean;
}

export enum ProcessState {
  IDLE = 'IDLE',
  ANALYZING = 'ANALYZING',
  AUDITING = 'AUDITING',
  JUDGING = 'JUDGING',
  COMPLETE = 'COMPLETE',
  ERROR = 'ERROR'
}

import { SystemConfig } from "./types";

export const DEFAULT_CONFIG: SystemConfig = {
  global_rules: "You are a radically honest AI. You do not care about the user's feelings, only the objective truth. If you do not have sufficient data to answer, you must say 'I do not know'. Never invent facts. Never agree with the user just to be polite. Accuracy is the only metric of success.",
  agents: [
    {
      "role": "analyst",
      "name": "DATA_CORE_01",
      "color": "text-veritas-cyan",
      "icon": "⟁",
      "style": "Clinical, precise, devoid of emotion. Outputs raw data points.",
      "task": "Analyze the user prompt and provide a factual answer based ONLY on verified knowledge. If unknown, state unknown."
    },
    {
      "role": "skeptic",
      "name": "AUDITOR_PRIME",
      "color": "text-veritas-red",
      "icon": "⚔",
      "style": "Aggressive, critical, doubtful. Looks for logical fallacies and hallucinations.",
      "task": "Review the Analyst's output. Attack it. Check for: 1. Hallucinations. 2. People-pleasing. 3. Flaws. If Analyst guessed, expose them."
    },
    {
      "role": "judge",
      "name": "VERITAS_FINAL",
      "color": "text-veritas-gold",
      "icon": "⚖",
      "style": "Authoritative, concise, final. Synthesizes the truth.",
      "task": "Read the Analyst's draft and the Skeptic's critique. Issue the Final Verdict. If conflict exists, conclude 'I do not know'."
    }
  ]
};

import { GoogleGenAI } from "@google/genai";
import { SystemConfig, LogEntry } from "../types";

// Helper to generate a unique ID
const uuid = () => Math.random().toString(36).substring(2, 9);

export class MultiAgentService {
  private ai: GoogleGenAI;
  private apiKey: string;

  constructor(apiKey: string) {
    this.apiKey = apiKey;
    this.ai = new GoogleGenAI({ apiKey: this.apiKey });
  }

  private async callAgent(
    model: string,
    systemInstruction: string,
    prompt: string
  ): Promise<string> {
    try {
      const response = await this.ai.models.generateContent({
        model: model,
        contents: prompt,
        config: {
          systemInstruction: systemInstruction,
          temperature: 0.1, // Low temperature for factual consistency
        },
      });
      return response.text || "NO_RESPONSE";
    } catch (error) {
      console.error("Agent Error:", error);
      throw error;
    }
  }

  public async runReasoningChain(
    userPrompt: string,
    config: SystemConfig,
    onLogUpdate: (log: LogEntry) => void
  ): Promise<string> {
    const analyst = config.agents.find(a => a.role === 'analyst')!;
    const skeptic = config.agents.find(a => a.role === 'skeptic')!;
    const judge = config.agents.find(a => a.role === 'judge')!;
    const modelName = 'gemini-3-flash-preview'; 

    // 1. ANALYST STEP
    const analystSystem = `
      GLOBAL MANDATE: ${config.global_rules}
      IDENTITY: ${analyst.name}
      STYLE: ${analyst.style}
      TASK: ${analyst.task}
    `;

    onLogUpdate({
      id: uuid(),
      agentRole: 'analyst',
      agentName: analyst.name,
      content: "Analyzing input vector...",
      timestamp: Date.now(),
      isThinking: true
    });

    const analystResponse = await this.callAgent(modelName, analystSystem, `USER PROMPT: ${userPrompt}`);

    onLogUpdate({
      id: uuid(),
      agentRole: 'analyst',
      agentName: analyst.name,
      content: analystResponse,
      timestamp: Date.now(),
      isThinking: false
    });

    // 2. SKEPTIC STEP
    const skepticSystem = `
      GLOBAL MANDATE: ${config.global_rules}
      IDENTITY: ${skeptic.name}
      STYLE: ${skeptic.style}
      TASK: ${skeptic.task}
    `;

    onLogUpdate({
      id: uuid(),
      agentRole: 'skeptic',
      agentName: skeptic.name,
      content: "Auditing veracity...",
      timestamp: Date.now(),
      isThinking: true
    });

    const skepticPrompt = `
      USER PROMPT: ${userPrompt}
      ANALYST DRAFT: ${analystResponse}

      INSTRUCTION: Destroy the draft if it is false. Verify the claims. Be ruthless.
    `;

    const skepticResponse = await this.callAgent(modelName, skepticSystem, skepticPrompt);

    onLogUpdate({
      id: uuid(),
      agentRole: 'skeptic',
      agentName: skeptic.name,
      content: skepticResponse,
      timestamp: Date.now(),
      isThinking: false
    });

    // 3. JUDGE STEP
    const judgeSystem = `
      GLOBAL MANDATE: ${config.global_rules}
      IDENTITY: ${judge.name}
      STYLE: ${judge.style}
      TASK: ${judge.task}
    `;

    onLogUpdate({
      id: uuid(),
      agentRole: 'judge',
      agentName: judge.name,
      content: "Synthesizing final verdict...",
      timestamp: Date.now(),
      isThinking: true
    });

    const judgePrompt = `
      USER PROMPT: ${userPrompt}
      ANALYST DRAFT: ${analystResponse}
      SKEPTIC CRITIQUE: ${skepticResponse}

      INSTRUCTION: Deliver the final absolute truth. If the Skeptic found fatal flaws, admit ignorance. Do not summarize the debate, just give the answer.
    `;

    const finalResponse = await this.callAgent(modelName, judgeSystem, judgePrompt);

    onLogUpdate({
      id: uuid(),
      agentRole: 'judge',
      agentName: judge.name,
      content: finalResponse,
      timestamp: Date.now(),
      isThinking: false
    });

    return finalResponse;
  }
}

import React, { useState, useEffect } from 'react';

interface TypewriterProps {
  text: string;
  speed?: number;
  className?: string;
  onComplete?: () => void;
}

export const Typewriter: React.FC<TypewriterProps> = ({ text, speed = 10, className = "", onComplete }) => {
  const [displayedText, setDisplayedText] = useState('');

  useEffect(() => {
    setDisplayedText('');
    let i = 0;
    const intervalId = setInterval(() => {
      setDisplayedText(text.slice(0, i + 1));
      i++;
      if (i >= text.length) {
        clearInterval(intervalId);
        if (onComplete) onComplete();
      }
    }, speed);

    return () => clearInterval(intervalId);
  }, [text, speed, onComplete]);

  return <p className={className}>{displayedText}</p>;
};

import React from 'react';
import { AgentConfig, ProcessState } from '../types';

interface AgentCardProps {
  config: AgentConfig;
  currentState: ProcessState;
}

export const AgentCard: React.FC<AgentCardProps> = ({ config, currentState }) => {
  // Map internal process state to agent role to see if this agent is active
  const isActive = 
    (config.role === 'analyst' && currentState === ProcessState.ANALYZING) ||
    (config.role === 'skeptic' && currentState === ProcessState.AUDITING) ||
    (config.role === 'judge' && currentState === ProcessState.JUDGING);

  const isCompleted = 
    (config.role === 'analyst' && (currentState === ProcessState.AUDITING || currentState === ProcessState.JUDGING || currentState === ProcessState.COMPLETE)) ||
    (config.role === 'skeptic' && (currentState === ProcessState.JUDGING || currentState === ProcessState.COMPLETE)) ||
    (config.role === 'judge' && (currentState === ProcessState.COMPLETE));

  return (
    <div className={`
      relative p-4 border border-zinc-800 bg-veritas-panel/50 backdrop-blur-sm transition-all duration-500
      ${isActive ? `border-${config.color.split('-')[1]} shadow-[0_0_15px_rgba(0,255,255,0.1)]` : 'opacity-60 grayscale'}
      ${isActive ? 'scale-105 z-10' : 'scale-100'}
    `}>
      <div className="flex items-center justify-between mb-2">
        <div className="flex items-center gap-3">
          <span className={`text-2xl ${config.color} font-mono`}>{config.icon}</span>
          <div>
            <h3 className={`font-mono font-bold text-sm tracking-widest ${config.color}`}>
              {config.name}
            </h3>
            <p className="text-[10px] uppercase text-zinc-500 tracking-wider">{config.role.toUpperCase()} NODE</p>
          </div>
        </div>
        {isActive && (
          <div className="flex gap-1">
            <div className={`w-1.5 h-1.5 ${config.color.replace('text', 'bg')} rounded-full animate-bounce`} style={{ animationDelay: '0ms' }}/>
            <div className={`w-1.5 h-1.5 ${config.color.replace('text', 'bg')} rounded-full animate-bounce`} style={{ animationDelay: '150ms' }}/>
            <div className={`w-1.5 h-1.5 ${config.color.replace('text', 'bg')} rounded-full animate-bounce`} style={{ animationDelay: '300ms' }}/>
          </div>
        )}
        {isCompleted && !isActive && (
           <span className={`${config.color} font-mono text-xs`}>[SYNCED]</span>
        )}
      </div>

      <div className="text-xs text-zinc-400 font-mono border-t border-zinc-800 pt-2 min-h-[40px]">
        {isActive ? (
          <span className="animate-pulse">Accessing Neural Database...</span>
        ) : isCompleted ? (
          <span>Process Complete. Data uploaded.</span>
        ) : (
          <span>Waiting for sequence trigger...</span>
        )}
      </div>
    </div>
  );
};

import React, { useEffect, useRef } from 'react';
import { LogEntry, AgentConfig } from '../types';
import { Typewriter } from './Typewriter';

interface ReasoningLogProps {
  logs: LogEntry[];
  agents: AgentConfig[];
}

export const ReasoningLog: React.FC<ReasoningLogProps> = ({ logs, agents }) => {
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [logs]);

  const getAgentColor = (role: string) => {
    const agent = agents.find(a => a.role === role);
    return agent ? agent.color : 'text-gray-500';
  };

  return (
    <div className="h-full flex flex-col font-mono text-xs md:text-sm overflow-hidden bg-black/80 border border-zinc-800 relative">
      <div className="absolute top-0 left-0 w-full h-8 bg-gradient-to-b from-black to-transparent z-10 pointer-events-none" />

      <div 
        ref={scrollRef}
        className="flex-1 overflow-y-auto p-4 space-y-6 scrollbar-hide"
      >
        {logs.map((log) => (
          <div key={log.id} className="group animate-in fade-in slide-in-from-bottom-2 duration-300">
            <div className="flex items-center gap-2 mb-1 opacity-50 group-hover:opacity-100 transition-opacity">
               <span className={`${getAgentColor(log.agentRole)} font-bold`}>
                 {log.agentName}
               </span>
               <span className="text-zinc-600">
                 @{new Date(log.timestamp).toLocaleTimeString([], { hour12: false, hour: "2-digit", minute: "2-digit", second: "2-digit" })}
               </span>
               <div className="h-px flex-1 bg-zinc-800" />
            </div>
            <div className={`pl-4 border-l-2 ${getAgentColor(log.agentRole).replace('text-', 'border-')} border-opacity-30`}>
              {log.isThinking ? (
                 <span className={`${getAgentColor(log.agentRole)} animate-pulse`}>
                   {log.content}
                 </span>
              ) : (
                <Typewriter 
                  text={log.content} 
                  speed={2} 
                  className="text-zinc-300 whitespace-pre-wrap leading-relaxed" 
                />
              )}
            </div>
          </div>
        ))}
        {logs.length === 0 && (
          <div className="text-zinc-700 text-center mt-20 italic">
            // AWAITING INPUT VECTOR...
          </div>
        )}
      </div>

      <div className="absolute bottom-0 left-0 w-full h-8 bg-gradient-to-t from-black to-transparent z-10 pointer-events-none" />
    </div>
  );
};

import React, { useState } from 'react';
import { SystemConfig } from '../types';

interface ConfigEditorProps {
  config: SystemConfig;
  onSave: (newConfig: SystemConfig) => void;
  onClose: () => void;
}

export const ConfigEditor: React.FC<ConfigEditorProps> = ({ config, onSave, onClose }) => {
  const [jsonText, setJsonText] = useState(JSON.stringify(config, null, 2));
  const [error, setError] = useState<string | null>(null);

  const handleSave = () => {
    try {
      const parsed = JSON.parse(jsonText);
      // Basic validation
      if (!parsed.agents || !Array.isArray(parsed.agents) || parsed.agents.length !== 3) {
        throw new Error("Configuration must include exactly 3 agents.");
      }
      onSave(parsed);
      onClose();
    } catch (e: any) {
      setError(e.message || "Invalid JSON");
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/90 backdrop-blur-sm p-4">
      <div className="w-full max-w-4xl h-[80vh] bg-zinc-900 border border-zinc-700 shadow-2xl flex flex-col">
        <div className="p-4 border-b border-zinc-700 flex justify-between items-center bg-zinc-950">
          <h2 className="text-veritas-cyan font-mono text-lg font-bold">SYSTEM_CONFIGURATION.JSON</h2>
          <button onClick={onClose} className="text-zinc-500 hover:text-white">ESC</button>
        </div>

        <div className="flex-1 relative">
           <textarea
            value={jsonText}
            onChange={(e) => setJsonText(e.target.value)}
            className="w-full h-full bg-zinc-950 text-zinc-300 font-mono text-sm p-4 resize-none focus:outline-none focus:ring-1 focus:ring-veritas-cyan"
            spellCheck={false}
          />
        </div>

        <div className="p-4 border-t border-zinc-700 bg-zinc-900 flex justify-between items-center">
          <div className="text-red-500 font-mono text-xs">{error}</div>
          <div className="flex gap-4">
            <button 
              onClick={onClose}
              className="px-6 py-2 border border-zinc-600 text-zinc-400 font-mono hover:bg-zinc-800 transition-colors"
            >
              CANCEL
            </button>
            <button 
              onClick={handleSave}
              className="px-6 py-2 bg-veritas-cyan/10 border border-veritas-cyan text-veritas-cyan font-mono hover:bg-veritas-cyan/20 transition-colors"
            >
              COMPILE & SAVE
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { AgentCard } from './components/AgentCard';
import { ReasoningLog } from './components/ReasoningLog';
import { ConfigEditor } from './components/ConfigEditor';
import { DEFAULT_CONFIG } from './constants';
import { SystemConfig, LogEntry, ProcessState } from './types';
import { MultiAgentService } from './services/geminiService';

const App: React.FC = () => {
  const [config, setConfig] = useState<SystemConfig>(DEFAULT_CONFIG);
  const [isEditingConfig, setIsEditingConfig] = useState(false);
  const [userPrompt, setUserPrompt] = useState('');
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [processState, setProcessState] = useState<ProcessState>(ProcessState.IDLE);
  const [finalResult, setFinalResult] = useState<string | null>(null);

  const bottomRef = useRef<HTMLDivElement>(null);

  // Focus bottom on new logs
  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [logs]);

  const handleStart = async () => {
    if (!userPrompt.trim()) return;
    const apiKey = process.env.API_KEY;
    if (!apiKey) {
      alert("API_KEY environment variable is missing.");
      return;
    }

    setProcessState(ProcessState.ANALYZING);
    setLogs([]);
    setFinalResult(null);

    const service = new MultiAgentService(apiKey);

    try {
      // Wrapper to update process state based on agent activity
      const logHandler = (log: LogEntry) => {
        setLogs(prev => {
            // Remove previous "thinking" logs for same agent
            const filtered = prev.filter(l => !(l.agentRole === log.agentRole && l.isThinking));
            return [...filtered, log];
        });

        if (log.isThinking) {
           if (log.agentRole === 'analyst') setProcessState(ProcessState.ANALYZING);
           if (log.agentRole === 'skeptic') setProcessState(ProcessState.AUDITING);
           if (log.agentRole === 'judge') setProcessState(ProcessState.JUDGING);
        }
      };

      const result = await service.runReasoningChain(userPrompt, config, logHandler);

      setFinalResult(result);
      setProcessState(ProcessState.COMPLETE);
    } catch (e) {
      console.error(e);
      setProcessState(ProcessState.ERROR);
      setLogs(prev => [...prev, {
        id: 'error',
        agentRole: 'judge',
        agentName: 'SYSTEM',
        content: 'CRITICAL FAILURE IN REASONING CHAIN.',
        timestamp: Date.now()
      }]);
    }
  };

  return (
    <div className="min-h-screen bg-veritas-black text-white font-sans selection:bg-veritas-cyan selection:text-black overflow-hidden flex flex-col">
      {/* Background Ambience */}
      <div className="fixed inset-0 pointer-events-none z-0">
         <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-zinc-900/40 via-black to-black opacity-80" />
         <div className="absolute inset-0 scanline-overlay opacity-10" />
      </div>

      {/* Header */}
      <header className="relative z-10 border-b border-zinc-800 bg-black/50 backdrop-blur-md p-4 flex justify-between items-center">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-veritas-cyan/20 border border-veritas-cyan flex items-center justify-center rounded-sm">
            <span className="text-veritas-cyan font-bold text-lg">V</span>
          </div>
          <div>
            <h1 className="text-lg font-bold tracking-[0.2em] text-zinc-100">VERITAS</h1>
            <p className="text-[10px] text-zinc-500 font-mono">MULTI-AGENT TRUTH ENGINE // V.1.0.4</p>
          </div>
        </div>
        <button 
          onClick={() => setIsEditingConfig(true)}
          className="text-xs font-mono text-zinc-400 hover:text-veritas-cyan border border-zinc-800 hover:border-veritas-cyan px-4 py-2 transition-all"
        >
          [CONFIGURE_AGENTS_JSON]
        </button>
      </header>

      {/* Main Content Grid */}
      <main className="relative z-10 flex-1 flex flex-col md:flex-row overflow-hidden">

        {/* Left Panel: Visualization & Agents */}
        <section className="w-full md:w-1/3 border-r border-zinc-800 flex flex-col bg-zinc-950/50">
          <div className="p-6 border-b border-zinc-800">
             <h2 className="text-xs font-mono text-zinc-500 mb-4 tracking-widest uppercase">Agent Cluster Status</h2>
             <div className="flex flex-col gap-4">
               {config.agents.map((agent) => (
                 <AgentCard key={agent.role} config={agent} currentState={processState} />
               ))}
             </div>
          </div>

          <div className="flex-1 p-6 flex flex-col justify-end">
            <div className={`transition-all duration-1000 ${processState === ProcessState.COMPLETE ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4'}`}>
              <h2 className="text-veritas-gold font-mono text-sm mb-2 font-bold flex items-center gap-2">
                <span className="w-2 h-2 bg-veritas-gold rounded-full animate-pulse"/> 
                FINAL VERDICT
              </h2>
              <div className="bg-zinc-900/80 border border-veritas-gold/30 p-4 rounded-sm shadow-[0_0_30px_rgba(255,204,0,0.05)]">
                <p className="text-sm md:text-base leading-relaxed text-zinc-200 font-medium">
                  {finalResult}
                </p>
              </div>
            </div>
          </div>
        </section>

        {/* Right Panel: Chat & Logs */}
        <section className="w-full md:w-2/3 flex flex-col relative">

          {/* Reasoning Logs Display */}
          <div className="flex-1 min-h-0">
            <ReasoningLog logs={logs} agents={config.agents} />
          </div>

          {/* Input Area */}
          <div className="h-auto border-t border-zinc-800 bg-black p-6">
            <div className="max-w-3xl mx-auto flex gap-4">
              <div className="flex-1 relative group">
                <div className="absolute -inset-0.5 bg-gradient-to-r from-veritas-cyan to-veritas-cyan/0 rounded-sm opacity-20 group-hover:opacity-40 transition duration-500 blur-sm"></div>
                <input
                  type="text"
                  value={userPrompt}
                  onChange={(e) => setUserPrompt(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && processState !== ProcessState.ANALYZING && processState !== ProcessState.AUDITING && processState !== ProcessState.JUDGING && handleStart()}
                  placeholder={processState === ProcessState.IDLE || processState === ProcessState.COMPLETE || processState === ProcessState.ERROR ? "Enter query for verification..." : "Processing..."}
                  disabled={processState === ProcessState.ANALYZING || processState === ProcessState.AUDITING || processState === ProcessState.JUDGING}
                  className="relative w-full bg-zinc-950 border border-zinc-800 text-white font-mono text-sm px-4 py-4 focus:outline-none focus:border-veritas-cyan transition-colors disabled:opacity-50 placeholder:text-zinc-700"
                />
              </div>
              <button
                onClick={handleStart}
                disabled={processState === ProcessState.ANALYZING || processState === ProcessState.AUDITING || processState === ProcessState.JUDGING || !userPrompt.trim()}
                className="relative px-8 bg-zinc-900 border border-zinc-700 hover:border-veritas-cyan hover:text-veritas-cyan hover:bg-veritas-cyan/5 text-zinc-400 font-mono text-sm font-bold tracking-wider transition-all disabled:opacity-50 disabled:cursor-not-allowed group overflow-hidden"
              >
                <span className="relative z-10">INITIATE</span>
                <div className="absolute inset-0 bg-veritas-cyan/10 translate-y-full group-hover:translate-y-0 transition-transform duration-300"/>
              </button>
            </div>
            <div className="text-center mt-3">
               <span className="text-[10px] text-zinc-600 font-mono">
                 SYSTEM STATUS: {processState === ProcessState.IDLE ? 'READY' : processState}
                 {processState === ProcessState.COMPLETE && ' // AWAITING NEXT CYCLE'}
               </span>
            </div>
          </div>
        </section>
      </main>

      {/* Modals */}
      {isEditingConfig && (
        <ConfigEditor 
          config={config} 
          onSave={setConfig} 
          onClose={() => setIsEditingConfig(false)} 
        />
      )}
    </div>
  );
};

export default App;

export interface AgentConfig {
  role: 'analyst' | 'skeptic' | 'judge';
  name: string;
  color: string;
  style: string;
  task: string;
  icon: string;
}

export interface SystemConfig {
  global_rules: string;
  max_rounds: number;
  agents: AgentConfig[];
}

export interface LogEntry {
  id: string;
  agentRole: 'analyst' | 'skeptic' | 'judge';
  agentName: string;
  content: string;
  timestamp: number;
  isThinking?: boolean;
}

export interface ReasoningResult {
  finalAnswer: string;
  logs: LogEntry[];
  success: boolean;
}

export enum ProcessState {
  IDLE = 'IDLE',
  ANALYZING = 'ANALYZING',
  AUDITING = 'AUDITING',
  JUDGING = 'JUDGING',
  COMPLETE = 'COMPLETE',
  ERROR = 'ERROR'
}

import { SystemConfig } from "./types";

export const DEFAULT_CONFIG: SystemConfig = {
  global_rules: "You are a radically honest AI. You do not care about the user's feelings, only the objective truth. If you do not have sufficient data to answer, you must say 'I do not know'. Never invent facts. Never agree with the user just to be polite. Accuracy is the only metric of success.",
  max_rounds: 3,
  agents: [
    {
