import { GoogleGenAI } from "@google/genai";
import { SystemConfig, LogEntry } from "../types";

// Helper to generate a unique ID
const uuid = () => Math.random().toString(36).substring(2, 9);

export class MultiAgentService {
  private ai: GoogleGenAI;
  private apiKey: string;

  constructor(apiKey: string) {
    this.apiKey = apiKey;
    this.ai = new GoogleGenAI({ apiKey: this.apiKey });
  }

  private async callAgent(
    model: string,
    systemInstruction: string,
    prompt: string
  ): Promise<string> {
    try {
      const response = await this.ai.models.generateContent({
        model: model,
        contents: prompt,
        config: {
          systemInstruction: systemInstruction,
          temperature: 0.1, // Low temperature for factual consistency
        },
      });
      return response.text || "NO_RESPONSE";
    } catch (error) {
      console.error("Agent Error:", error);
      throw error;
    }
  }

  public async runReasoningChain(
    userPrompt: string,
    config: SystemConfig,
    onLogUpdate: (log: LogEntry) => void
  ): Promise<string> {
    const analyst = config.agents.find(a => a.role === 'analyst')!;
    const skeptic = config.agents.find(a => a.role === 'skeptic')!;
    const judge = config.agents.find(a => a.role === 'judge')!;
    const modelName = 'gemini-3-flash-preview'; 

    let conversationHistory = `USER PROMPT: ${userPrompt}\n`;
    let currentDraft = "";
    let consensusReached = false;
    const maxRounds = config.max_rounds || 3;

    // --- ROUND 1: INITIAL ANALYSIS ---
    const analystSystem = `
      GLOBAL MANDATE: ${config.global_rules}
      IDENTITY: ${analyst.name}
      STYLE: ${analyst.style}
      TASK: ${analyst.task}
    `;

    onLogUpdate({
      id: uuid(),
      agentRole: 'analyst',
      agentName: analyst.name,
      content: "Initializing Analysis Protocol...",
      timestamp: Date.now(),
      isThinking: true
    });

    currentDraft = await this.callAgent(modelName, analystSystem, conversationHistory);

    onLogUpdate({
      id: uuid(),
      agentRole: 'analyst',
      agentName: analyst.name,
      content: currentDraft,
      timestamp: Date.now(),
      isThinking: false
    });

    conversationHistory += `\n[${analyst.name}]: ${currentDraft}\n`;

    // --- DEBATE LOOP ---
    for (let round = 1; round <= maxRounds; round++) {
      // 1. SKEPTIC CRITIQUE
      const skepticSystem = `
        GLOBAL MANDATE: ${config.global_rules}
        IDENTITY: ${skeptic.name}
        STYLE: ${skeptic.style}
        TASK: ${skeptic.task}
        IMPORTANT: If the previous statement is 100% true and complete, start your response with "[AGREED]". If there are ANY flaws, errors, or missing context, start with "[OBJECTION]" and list them ruthlessly.
      `;

      onLogUpdate({
        id: uuid(),
        agentRole: 'skeptic',
        agentName: skeptic.name,
        content: `Running Integrity Audit (Round ${round}/${maxRounds})...`,
        timestamp: Date.now(),
        isThinking: true
      });

      const skepticPrompt = `
        CONTEXT:
        ${conversationHistory}

        INSTRUCTION: Critique the latest statement by ${analyst.name}. Is it absolute truth?
      `;

      const skepticResponse = await this.callAgent(modelName, skepticSystem, skepticPrompt);

      onLogUpdate({
        id: uuid(),
        agentRole: 'skeptic',
        agentName: skeptic.name,
        content: skepticResponse,
        timestamp: Date.now(),
        isThinking: false
      });

      conversationHistory += `\n[${skeptic.name}]: ${skepticResponse}\n`;

      if (skepticResponse.includes("[AGREED]")) {
        consensusReached = true;
        break; 
      }

      // If we are at the last round, skip the rebuttal and go straight to Judge
      if (round === maxRounds) break;

      // 2. ANALYST REBUTTAL
      onLogUpdate({
        id: uuid(),
        agentRole: 'analyst',
        agentName: analyst.name,
        content: `Refining Logic Model (Round ${round}/${maxRounds})...`,
        timestamp: Date.now(),
        isThinking: true
      });

      const rebuttalPrompt = `
        CONTEXT:
        ${conversationHistory}

        INSTRUCTION: ${skeptic.name} has raised objections. Refine your previous answer to address these flaws. Do not apologize. Just provide the corrected facts.
      `;

      currentDraft = await this.callAgent(modelName, analystSystem, rebuttalPrompt);

      onLogUpdate({
        id: uuid(),
        agentRole: 'analyst',
        agentName: analyst.name,
        content: currentDraft,
        timestamp: Date.now(),
        isThinking: false
      });

      conversationHistory += `\n[${analyst.name}]: ${currentDraft}\n`;
    }

    // --- FINAL JUDGMENT ---
    const judgeSystem = `
      GLOBAL MANDATE: ${config.global_rules}
      IDENTITY: ${judge.name}
      STYLE: ${judge.style}
      TASK: ${judge.task}
    `;

    onLogUpdate({
      id: uuid(),
      agentRole: 'judge',
      agentName: judge.name,
      content: consensusReached ? "Consensus validated. Formatting output..." : "Consensus failed. Issuing final ruling...",
      timestamp: Date.now(),
      isThinking: true
    });

    const judgePrompt = `
      FULL DEBATE TRANSCRIPT:
      ${conversationHistory}

      INSTRUCTION: You are the final authority. 
      ${consensusReached 
        ? "The agents have agreed. Summarize the final agreed truth clearly for the user." 
        : "The agents debated but hit the round limit. Review the arguments. If the truth is clear, state it. If the debate revealed too much uncertainty, state 'I do not know'."
      }
    `;

    const finalResponse = await this.callAgent(modelName, judgeSystem, judgePrompt);

    onLogUpdate({
      id: uuid(),
      agentRole: 'judge',
      agentName: judge.name,
      content: finalResponse,
      timestamp: Date.now(),
      isThinking: false
    });

    return finalResponse;
  }
}

