        {/* Status Indicator */}
        <div className="flex flex-col items-end">
             {isActive ? (
               <div className="flex items-center gap-1">
                 <span className={`${config.color} text-[9px] font-bold animate-pulse`}>PROCESSING</span>
                 <div className={`w-2 h-2 rounded-sm ${config.color.replace('text-', 'bg-')}`}></div>
               </div>
             ) : isCompleted ? (
                <span className="text-zinc-600 text-[9px]">STANDBY</span>
             ) : (
                <span className="text-zinc-700 text-[9px]">OFFLINE</span>
             )}
        </div>
      </div>

