                 </span>
              </div>

              {/* Content Body */}
              <div className={`pl-4 border-l ${getAgentColor(log.agentRole).replace('text-', 'border-')} ml-1`}>
                {log.isThinking ? (
                   <span className={`${getAgentColor(log.agentRole)} animate-pulse italic`}>
