        });

        if (log.isThinking) {
           if (log.agentRole === 'analyst') setProcessState(ProcessState.ANALYZING);
           if (log.agentRole === 'skeptic') setProcessState(ProcessState.AUDITING);
           if (log.agentRole === 'judge') setProcessState(ProcessState.JUDGING);
        }
      };

      const result = await service.runReasoningChain(userPrompt, config, logHandler);

      setFinalResult(result);
      setProcessState(ProcessState.COMPLETE);
    } catch (e) {
      console.error(e);
      setProcessState(ProcessState.ERROR);
      setLogs(prev => [...prev, {
        id: 'error',
        agentRole: 'judge',
        agentName: 'SYSTEM',
        content: 'CRITICAL FAILURE IN REASONING CHAIN.',
        timestamp: Date.now()
      }]);
