import { GoogleGenAI, Type, Schema } from "@google/genai";
import { SystemConfig, LogEntry, AgentConfig, ChatHistoryItem } from "../types";
import { generateSystemInstruction, ANALYST_PROMPT, SKEPTIC_PROMPT, JUDGE_PROMPT, META_INSPECTION_PROMPT } from "./prompts";

// Schemas
const ANALYST_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    thought_process: { type: Type.STRING, description: "Hidden reasoning steps" },
    factual_answer: { type: Type.STRING, description: "The proposed truth" },
    confidence: { type: Type.NUMBER, description: "0-100 certainty score" },
  },
  required: ["thought_process", "factual_answer", "confidence"],
};

const SKEPTIC_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    analysis: { type: Type.STRING, description: "Critique of the input" },
    has_flaws: { type: Type.BOOLEAN, description: "True if errors exist" },
    flaws: { type: Type.ARRAY, items: { type: Type.STRING }, description: "List of specific errors" },
    correction: { type: Type.STRING, description: "Proposed fix" },
  },
  required: ["analysis", "has_flaws", "flaws", "correction"],
};

const JUDGE_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    debate_summary: { type: Type.STRING, description: "Brief recap of the argument" },
    final_verdict: { type: Type.STRING, description: "The absolute final answer for the user" },
    is_conclusive: { type: Type.BOOLEAN },
  },
  required: ["debate_summary", "final_verdict"],
};

const META_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    response: { type: Type.STRING, description: "The agent's explanation of its own state" },
    internal_state: { type: Type.STRING, description: "Technical status or mode description" }
  },
  required: ["response", "internal_state"]
};

const uuid = () => Math.random().toString(36).substring(2, 9);

export class MultiAgentService {
  private ai: GoogleGenAI;

  constructor(apiKey: string) {
    this.ai = new GoogleGenAI({ apiKey });
  }

  /**
   * Cleans raw model output (which might include markdown code blocks) and parses it.
   */
  private cleanAndParseJSON(text: string): any {
    try {
      // Remove markdown code blocks if present (e.g. ```json ... ```)
      const cleanText = text.replace(/```json\n?|\n?```/g, "").trim();
      return JSON.parse(cleanText);
    } catch (e) {
      console.error("JSON Parse Error. Raw text:", text);
      throw new Error("Failed to parse agent response. The agent may have deviated from the protocol.");
    }
  }

  private async callAgentJSON(
    model: string,
    systemPrompt: string,
    userPrompt: string,
    schema: Schema,
    useTools: boolean = false
  ): Promise<{ data: any; sources?: any[] }> {
    try {
      // Configuration for Gemini 3
      const config: any = {
        systemInstruction: systemPrompt,
        responseMimeType: "application/json",
        responseSchema: schema,
        temperature: 0.1, // Strict logic for truth
      };

      // Add Search Tool & Thinking Config
      if (useTools) {
        config.tools = [{ googleSearch: {} }];
        // Increased thinking budget for Pro model to ensure deep reasoning
        config.thinkingConfig = { thinkingBudget: 2048 }; 
      }

      const response = await this.ai.models.generateContent({
        model,
        contents: userPrompt,
        config,
      });

      const text = response.text;
      const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;

      if (!text) throw new Error("Empty response from AI");

      return {
        data: this.cleanAndParseJSON(text),
        sources: groundingChunks
      };
    } catch (error) {
      console.error("Agent Execution Failed:", error);
      throw error;
    }
  }

  public async interrogateAgent(
    targetAgentRole: string,
    userQuery: string,
    config: SystemConfig,
    chatHistory: ChatHistoryItem[],
    onLog: (log: LogEntry) => void
  ): Promise<string> {
    const modelName = 'gemini-3-flash-preview'; // Flash is sufficient for meta-analysis
    const agent = config.agents.find(a => a.role === targetAgentRole);

    if (!agent) throw new Error(`Agent ${targetAgentRole} not found`);

    // Format previous history
    let contextBlock = "";
    if (chatHistory.length > 0) {
        contextBlock = "PREVIOUS SESSION LOGS:\n" + chatHistory.map(turn => 
            `${turn.role === 'user' ? 'USER' : 'SYSTEM'}: ${turn.content}`
        ).join("\n") + "\n\n";
    }

    onLog(this.createLog(agent.role, agent.name, "Running self-diagnostic...", true));

    const response = await this.callAgentJSON(
      modelName,
      generateSystemInstruction(agent, config),
      META_INSPECTION_PROMPT(contextBlock, userQuery),
      META_SCHEMA,
      false
    );

    onLog(this.createLog(
      agent.role, 
      agent.name, 
      response.data.response, 
      false, 
      { thought_process: response.data.internal_state }
    ));

    return response.data.response;
  }

  public async runReasoningChain(
    userPrompt: string,
    config: SystemConfig,
    chatHistory: ChatHistoryItem[],
    onLog: (log: LogEntry) => void,
    onRoundUpdate?: (round: number) => void
  ): Promise<string> {
    // Upgraded to PRO model for complex STEM/Reasoning tasks
    const modelName = 'gemini-3-pro-preview';
    const analyst = config.agents.find(a => a.role === 'analyst')!;
    const skeptic = config.agents.find(a => a.role === 'skeptic')!;
    const judge = config.agents.find(a => a.role === 'judge')!;

    // Format previous history
    let contextBlock = "";
    if (chatHistory.length > 0) {
        contextBlock = "PREVIOUS CONVERSATION CONTEXT:\n" + chatHistory.map(turn => 
            `${turn.role === 'user' ? 'USER' : 'VERITAS_SYSTEM'}: ${turn.content}`
        ).join("\n") + "\n\n";
    }

    // Initialize the Debate Transcript (The "Room") with context + new prompt
    let debateTranscript = `${contextBlock}CURRENT USER QUERY: "${userPrompt}"\n`;
    let currentDraft = "";
    let consensus = false;
    let roundsExecuted = 0;

    // --- ANALYST (Round 0) ---
    onLog(this.createLog('analyst', analyst.name, "Initializing deep scan & logic vectors...", true));

    // Analyst gets Search Tools & Thinking
    const analystRes = await this.callAgentJSON(
      modelName,
      generateSystemInstruction(analyst, config),
      ANALYST_PROMPT(debateTranscript),
      ANALYST_SCHEMA,
      true // Enable Search & Thinking
    );

    currentDraft = analystRes.data.factual_answer;
    debateTranscript += `\n[${analyst.name}]: ${currentDraft}\n(Confidence: ${analystRes.data.confidence}%)\n`;

    onLog(this.createLog(
      'analyst', 
      analyst.name, 
      analystRes.data.factual_answer, 
      false, 
      analystRes.data,
      analystRes.sources
    ));

    // --- DEBATE LOOP ---
    for (let i = 1; i <= config.max_rounds; i++) {
      roundsExecuted = i;
      if (onRoundUpdate) onRoundUpdate(i);

      // SKEPTIC
      onLog(this.createLog('skeptic', skeptic.name, `Running integrity check (Cycle ${i})...`, true));

      // Skeptic gets Search Tools to verify claims
      const skepticRes = await this.callAgentJSON(
        modelName,
        generateSystemInstruction(skeptic, config),
        SKEPTIC_PROMPT(debateTranscript, currentDraft),
        SKEPTIC_SCHEMA,
        true // Enable Tools for Verification
      );

      debateTranscript += `\n[${skeptic.name}]: ${skepticRes.data.analysis}\nFlaws: ${skepticRes.data.flaws.join(", ")}\n`;

      const skepticLogContent = skepticRes.data.has_flaws 
        ? `OBJECTION: ${skepticRes.data.analysis}`
        : `AGREEMENT: ${skepticRes.data.analysis}`;

      onLog(this.createLog(
        'skeptic', 
        skeptic.name, 
        skepticLogContent, 
        false, 
        skepticRes.data,
        skepticRes.sources // Log Skeptic's verification sources
      ));

      if (!skepticRes.data.has_flaws) {
        consensus = true;
        break;
      }

      if (i === config.max_rounds) break;

      // ANALYST REBUTTAL
      onLog(this.createLog('analyst', analyst.name, "Processing critique & refining...", true));

      const rebuttalRes = await this.callAgentJSON(
        modelName,
        generateSystemInstruction(analyst, config),
        `CRITIQUE RECEIVED: ${skepticRes.data.analysis}\nSUGGESTED CORRECTION: ${skepticRes.data.correction}\n\nRefine your answer.`,
        ANALYST_SCHEMA,
        true // Enable Search & Thinking for rebuttal
      );

      currentDraft = rebuttalRes.data.factual_answer;
      debateTranscript += `\n[${analyst.name} (Refined)]: ${currentDraft}\n`;
      onLog(this.createLog(
        'analyst', 
        analyst.name, 
        currentDraft, 
        false, 
        rebuttalRes.data,
        rebuttalRes.sources
      ));
    }

    // --- JUDGE ---
    onLog(this.createLog('judge', judge.name, "Compiling final verdict...", true));

    const judgeRes = await this.callAgentJSON(
      modelName,
      generateSystemInstruction(judge, config),
      JUDGE_PROMPT(debateTranscript, consensus, roundsExecuted),
      JUDGE_SCHEMA
    );

    onLog(this.createLog(
      'judge', 
      judge.name, 
      judgeRes.data.final_verdict, 
      false, 
      judgeRes.data
    ));

    return judgeRes.data.final_verdict;
  }

  private createLog(
    role: any, 
    name: string, 
    content: string, 
    isThinking: boolean, 
    metadata?: any, 
    sources?: any[]
  ): LogEntry {
    return {
      id: uuid(),
      agentRole: role,
      agentName: name,
      content,
      isThinking,
      timestamp: Date.now(),
      metadata,
      sources
    };
  }
}

import { useState, useCallback } from 'react';
import { SystemConfig, LogEntry, ProcessState, ChatHistoryItem } from '../types';
import { MultiAgentService } from '../services/geminiService';

export const useReasoningEngine = (config: SystemConfig) => {
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [processState, setProcessState] = useState<ProcessState>(ProcessState.IDLE);
  const [finalResult, setFinalResult] = useState<string | null>(null);
  const [chatHistory, setChatHistory] = useState<ChatHistoryItem[]>([]);
  const [currentRound, setCurrentRound] = useState<number>(0);

  const startReasoning = useCallback(async (userPrompt: string) => {
    const apiKey = process.env.API_KEY;
    if (!apiKey) {
      console.error("API Key missing");
      return;
    }

    // Reset UI state for new operation
    setProcessState(ProcessState.ANALYZING);
    setFinalResult(null);
    setCurrentRound(0);

    // Add visual separator for new turn if not the first one
    if (logs.length > 0) {
      setLogs(prev => [...prev, {
        id: `sep-${Date.now()}`,
        agentRole: 'system',
        agentName: 'SYSTEM',
        content: '-------------------------------- NEW SESSION TURN --------------------------------',
        timestamp: Date.now()
      }]);
    }

    const service = new MultiAgentService(apiKey);

    // Check for Meta-Interrogation Command (e.g., "@DATA_CORE_01: status report")
    const interrogationMatch = userPrompt.match(/^@([^:]+):(.+)$/);

    try {
      if (interrogationMatch) {
         const targetName = interrogationMatch[1].trim();
         const query = interrogationMatch[2].trim();
         const agent = config.agents.find(a => a.name === targetName);

         if (agent) {
            // META INTERROGATION MODE
            const result = await service.interrogateAgent(
                agent.role,
                query,
                config,
                chatHistory,
                (log) => setLogs(prev => [...prev, log])
            );
             setFinalResult(result);
             setProcessState(ProcessState.COMPLETE);
             return;
         }
      }

      // STANDARD REASONING CHAIN
      const result = await service.runReasoningChain(
        userPrompt, 
        config,
        chatHistory, 
        (log) => {
          setLogs(prev => {
            // Remove previous thinking log from same agent
            const filtered = prev.filter(l => !(l.agentRole === log.agentRole && l.isThinking));
            return [...filtered, log];
          });

          if (log.isThinking) {
             const stateMap: Record<string, ProcessState> = {
               'analyst': ProcessState.ANALYZING,
               'skeptic': ProcessState.AUDITING,
               'judge': ProcessState.JUDGING
             };
             if (stateMap[log.agentRole]) setProcessState(stateMap[log.agentRole]);
          }
        },
        (round) => {
            setCurrentRound(round);
        }
      );

      setFinalResult(result);
      setProcessState(ProcessState.COMPLETE);

      // Update Short-Term Memory
      setChatHistory(prev => [
        ...prev,
        { role: 'user', content: userPrompt },
        { role: 'model', content: result }
      ]);

    } catch (e) {
      console.error(e);
      setProcessState(ProcessState.ERROR);
      setLogs(prev => [...prev, {
        id: 'ERR', 
        agentRole: 'judge', 
        agentName: 'SYSTEM', 
        content: 'CRITICAL FAILURE', 
        timestamp: Date.now()
      }]);
    }
  }, [config, chatHistory, logs.length]); 

  const clearMemory = useCallback(() => {
    setChatHistory([]);
    setLogs([]);
    setFinalResult(null);
    setProcessState(ProcessState.IDLE);
    setCurrentRound(0);
  }, []);

  return {
    logs,
    processState,
    finalResult,
    currentRound,
    startReasoning,
    clearMemory
  };
};

import React from 'react';
import { AgentConfig, ProcessState } from '../types';

interface AgentCardProps {
  config: AgentConfig;
  currentState: ProcessState;
  onInterrogate?: (agentName: string) => void;
}

export const AgentCard: React.FC<AgentCardProps> = ({ config, currentState, onInterrogate }) => {
  // Map internal process state to agent role
  const isActive = 
    (config.role === 'analyst' && currentState === ProcessState.ANALYZING) ||
    (config.role === 'skeptic' && currentState === ProcessState.AUDITING) ||
    (config.role === 'judge' && currentState === ProcessState.JUDGING);

  const isCompleted = 
    (config.role === 'analyst' && (currentState === ProcessState.AUDITING || currentState === ProcessState.JUDGING || currentState === ProcessState.COMPLETE)) ||
    (config.role === 'skeptic' && (currentState === ProcessState.JUDGING || currentState === ProcessState.COMPLETE)) ||
    (config.role === 'judge' && (currentState === ProcessState.COMPLETE));

  // Dynamic border color based on state
  const borderColor = isActive 
    ? config.color.replace('text-', 'border-') 
    : 'border-zinc-800';

  const bgColor = isActive
    ? 'bg-zinc-900'
    : 'bg-black';

  return (
    <div className={`
      relative group overflow-hidden transition-all duration-300
      border-l-2 border-r border-t border-b ${borderColor}
      ${bgColor}
      ${isActive ? 'shadow-[0_0_20px_rgba(0,0,0,0.5)] z-20 scale-105' : 'opacity-70 scale-100'}
      h-32 flex flex-col
    `}>
      {/* HUD Corners */}
      <div className="absolute top-0 right-0 w-2 h-2 border-t border-r border-zinc-600"></div>
      <div className="absolute bottom-0 left-0 w-2 h-2 border-b border-l border-zinc-600"></div>

      {/* Background Active Scanline */}
      {isActive && (
        <div className="absolute inset-0 bg-repeat-y opacity-10 pointer-events-none bg-[url('https://www.transparenttextures.com/patterns/diagmonds-light.png')]"></div>
      )}

      {/* Header */}
      <div className="flex items-center justify-between p-3 border-b border-zinc-800 bg-black/40">
        <div className="flex items-center gap-3">
          <div className={`w-8 h-8 flex items-center justify-center border ${config.color.replace('text-', 'border-')} bg-zinc-900`}>
            <span className={`${config.color} text-lg`}>{config.icon}</span>
          </div>
          <div>
            <h3 className={`font-mono font-bold text-sm tracking-widest ${config.color} leading-none mb-1`}>
              {config.name}
            </h3>
            <p className="text-[9px] uppercase text-zinc-500 font-mono tracking-wider">
              ID: {config.role.substring(0,3).toUpperCase()}_00{Math.floor(Math.random()*99)}
            </p>
          </div>
        </div>

        {/* Status Indicator / Actions */}
        <div className="flex flex-col items-end gap-1">
             {isActive ? (
               <div className="flex items-center gap-1">
                 <span className={`${config.color} text-[9px] font-bold animate-pulse`}>PROCESSING</span>
                 <div className={`w-2 h-2 rounded-sm ${config.color.replace('text-', 'bg-')}`}></div>
               </div>
             ) : (
               <button 
                  onClick={() => onInterrogate && onInterrogate(config.name)}
                  className="text-[9px] border border-zinc-700 px-1.5 py-0.5 hover:bg-zinc-800 hover:text-white hover:border-zinc-500 transition-colors uppercase tracking-widest"
                  title="Query Agent Internal State"
               >
                  QRY
               </button>
             )}
        </div>
      </div>

      {/* Content Area - Visualization of Activity */}
      <div className="flex-1 p-3 relative overflow-hidden">
        {isActive ? (
          <div className="flex gap-1 h-full items-end">
            {[...Array(12)].map((_, i) => (
              <div 
                key={i} 
                className={`w-1 ${config.color.replace('text-', 'bg-')} opacity-80`}
                style={{ 
                  height: `${Math.random() * 100}%`,
                  animation: `pulse 0.${5 + i}s infinite alternate`
                }} 
              />
            ))}
          </div>
        ) : (
          <div className="h-full w-full flex items-center justify-center">
             <div className="h-px w-full bg-zinc-800"></div>
          </div>
        )}
      </div>

      {/* Decorative Bottom Bar */}
      <div className={`h-0.5 w-full ${isActive ? config.color.replace('text-', 'bg-') : 'bg-zinc-800'}`}></div>
    </div>
  );
};

import React, { useState, useEffect, useCallback } from 'react';
import { AgentCard } from './features/reasoning/components/AgentCard';
import { ReasoningLog } from './features/reasoning/components/ReasoningLog';
import { ConfigEditor } from './features/reasoning/components/ConfigEditor';
import { TerminalText } from './components/TerminalText';
import { DEFAULT_CONFIG, PRESETS } from './features/reasoning/constants';
import { SystemConfig, ProcessState } from './features/reasoning/types';
import { useReasoningEngine } from './features/reasoning/hooks/useReasoningEngine';
import { useSoundFX } from './features/reasoning/hooks/useSoundFX';

const CONFIG_STORAGE_KEY = 'veritas_system_config';

const App: React.FC = () => {
  // Sound Engine
  const { playBlip, playClick, playActivate, playDataStream, playVerdict, playError } = useSoundFX();

  // Load config
  const [config, setConfig] = useState<SystemConfig>(() => {
    try {
      const saved = localStorage.getItem(CONFIG_STORAGE_KEY);
      return saved ? JSON.parse(saved) : DEFAULT_CONFIG;
    } catch (e) {
      return DEFAULT_CONFIG;
    }
  });

  const [activePreset, setActivePreset] = useState<string>('DEFAULT');
  const [isEditingConfig, setIsEditingConfig] = useState(false);
  const [userPrompt, setUserPrompt] = useState('');

  const { logs, processState, finalResult, currentRound, startReasoning, clearMemory } = useReasoningEngine(config);

  // Audio Triggers based on State
  useEffect(() => {
    if (processState === ProcessState.ANALYZING) playActivate();
    if (processState === ProcessState.AUDITING) playDataStream();
    if (processState === ProcessState.COMPLETE) playVerdict();
    if (processState === ProcessState.ERROR) playError();
  }, [processState, playActivate, playDataStream, playVerdict, playError]);

  // Audio Trigger on new logs
  useEffect(() => {
    if (logs.length > 0) {
        playBlip();
    }
  }, [logs.length, playBlip]);

  // Global Keyboard Shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        if (e.metaKey || e.ctrlKey) {
            if (e.key === 'k') {
                e.preventDefault();
                playClick();
                clearMemory();
            }
            if (e.key === 'Enter') {
                // If focus is not in textarea
                const active = document.activeElement;
                if (active?.tagName !== 'TEXTAREA') {
                   // handleExecute() - tricky to access state closure here without refs, 
                   // but user is likely in textarea for input.
                }
            }
        }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [clearMemory, playClick]);

  const handleSaveConfig = (newConfig: SystemConfig) => {
    setConfig(newConfig);
    localStorage.setItem(CONFIG_STORAGE_KEY, JSON.stringify(newConfig));
    setIsEditingConfig(false);
    setActivePreset('CUSTOM');
    playVerdict();
  };

  const handlePresetChange = (key: string) => {
      playClick();
      setActivePreset(key);
      setConfig(PRESETS[key]);
  };

  const handleExecute = () => {
    if (userPrompt.trim()) {
        playActivate();
        startReasoning(userPrompt);
    }
  };

  const handleExport = () => {
    playClick();
    const dataStr = JSON.stringify(logs, null, 2);
    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `veritas_transcript_${Date.now()}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleInterrogate = (agentName: string) => {
      playClick();
      setUserPrompt(`@${agentName}: `);
      // Optional: focus textarea
      const textarea = document.querySelector('textarea');
      if (textarea) textarea.focus();
  };

  const isProcessing = processState !== ProcessState.IDLE && processState !== ProcessState.COMPLETE && processState !== ProcessState.ERROR;

  return (
    <div className="h-screen w-screen bg-veritas-black text-white font-sans selection:bg-veritas-cyan selection:text-black flex flex-col overflow-hidden crt-flicker">

      {/* HEADER */}
      <header className="h-14 border-b border-zinc-800 bg-black flex justify-between items-center px-6 relative z-50">
        <div className="flex items-center gap-4">
          <div className="w-6 h-6 bg-veritas-cyan flex items-center justify-center cursor-pointer hover:opacity-80 transition-opacity" onClick={playVerdict}>
            <span className="text-black font-bold text-xs">V</span>
          </div>
          <div className="flex flex-col">
            <h1 className="text-lg font-bold tracking-[0.2em] text-white leading-none">VERITAS</h1>
            <span className="text-[9px] text-zinc-500 font-mono tracking-widest">MULTI-AGENT TRUTH ENGINE</span>
          </div>

          {/* PRESET SELECTOR */}
          <div className="hidden md:flex ml-8 bg-zinc-900 rounded-sm border border-zinc-800 p-0.5">
             {Object.keys(PRESETS).map(key => (
                 <button
                    key={key}
                    onClick={() => handlePresetChange(key)}
                    className={`px-3 py-1 text-[9px] font-mono tracking-wider transition-all ${activePreset === key ? 'bg-veritas-cyan text-black font-bold' : 'text-zinc-500 hover:text-white'}`}
                 >
                    {key}
                 </button>
             ))}
             {activePreset === 'CUSTOM' && (
                 <span className="px-3 py-1 text-[9px] font-mono tracking-wider bg-zinc-800 text-zinc-300">CUSTOM</span>
             )}
          </div>
        </div>

        {/* CENTER STATUS - CYCLE INDICATOR */}
        {isProcessing && currentRound > 0 && (
          <div className="hidden lg:flex flex-col items-center justify-center absolute left-1/2 transform -translate-x-1/2">
             <div className="flex items-center gap-1 mb-1">
               <span className="text-[9px] text-veritas-gold font-mono tracking-widest animate-pulse">RECURSIVE CYCLE {currentRound} / {config.max_rounds}</span>
             </div>
             <div className="flex gap-1">
                {[...Array(config.max_rounds)].map((_, i) => (
                  <div 
                    key={i} 
                    className={`h-1 w-8 rounded-full transition-colors duration-500 ${i < currentRound ? 'bg-veritas-gold' : 'bg-zinc-800'}`}
                  ></div>
                ))}
             </div>
          </div>
        )}

        <div className="flex items-center gap-6">
          <div className="hidden md:flex items-center gap-2">
            <span className={`w-2 h-2 rounded-full ${isProcessing ? 'bg-veritas-red animate-pulse' : 'bg-zinc-700'}`}></span>
            <span className="text-[10px] font-mono text-zinc-400">STATUS: {processState}</span>
          </div>
          <div className="flex gap-2">
             <button 
              onClick={handleExport}
              className="text-[10px] font-mono text-zinc-400 border border-zinc-800 px-3 py-1 hover:bg-zinc-900 transition-colors uppercase"
              title="Export Transcript JSON (Ctrl+E)"
            >
              EXP
            </button>
            <button 
              onClick={() => { playClick(); clearMemory(); }}
              className="text-[10px] font-mono text-zinc-400 border border-zinc-800 px-3 py-1 hover:bg-zinc-900 hover:text-veritas-red transition-colors uppercase"
              title="Reset Memory & Logs (Ctrl+K)"
            >
              RST
            </button>
            <button 
              onClick={() => { playClick(); setIsEditingConfig(true); }}
              className="text-[10px] font-mono text-veritas-cyan border border-veritas-cyan/30 px-3 py-1 hover:bg-veritas-cyan/10 transition-colors uppercase"
            >
              CFG
            </button>
          </div>
        </div>
      </header>

      {/* MAIN CONTENT */}
      <main className="flex-1 flex overflow-hidden relative">
        <div className="absolute inset-0 bg-grid-pattern opacity-10 pointer-events-none"></div>

        {/* SIDEBAR */}
        <aside className="w-80 border-r border-zinc-800 bg-black/50 backdrop-blur-sm flex flex-col relative z-20">
          <div className="p-4 border-b border-zinc-800 bg-zinc-900/50">
            <h2 className="text-[10px] font-mono text-zinc-500 uppercase tracking-widest mb-1">Active Neural Nodes</h2>
          </div>
          <div className="flex-1 p-4 space-y-4 overflow-y-auto">
             {config.agents.map((agent) => (
               <AgentCard 
                    key={agent.role} 
                    config={agent} 
                    currentState={processState} 
                    onInterrogate={handleInterrogate}
                />
             ))}
          </div>
        </aside>

        {/* CENTER DASHBOARD */}
        <section className="flex-1 flex flex-col min-w-0 bg-black/20 relative z-10">
          <div className="flex-1 relative border-b border-zinc-800">
             <ReasoningLog logs={logs} agents={config.agents} />

             {/* VERDICT OVERLAY */}
             <div className={`absolute bottom-0 left-0 right-0 bg-zinc-950/95 border-t border-veritas-gold transition-all duration-700 transform ${finalResult ? 'translate-y-0 opacity-100' : 'translate-y-full opacity-0'}`}>
               <div className="p-8 max-w-4xl mx-auto">
                 <div className="flex items-center gap-3 mb-4">
                   <span className="text-veritas-gold text-2xl">⚖</span>
                   <h2 className="text-veritas-gold font-mono text-xl font-bold tracking-widest">FINAL VERDICT</h2>
                 </div>
                 {finalResult && (
                   <TerminalText 
                     text={finalResult} 
                     speed={10} 
                     scramble={false}
                     className="text-lg md:text-xl text-white font-medium leading-relaxed font-sans" 
                   />
                 )}
               </div>
             </div>
          </div>

          {/* INPUT AREA */}
          <div className="h-24 bg-black border-t border-zinc-800 p-4 flex gap-4 items-center">
             <div className="flex-1 relative h-full">
               <textarea 
                 value={userPrompt}
                 onChange={(e) => setUserPrompt(e.target.value)}
                 onKeyDown={(e) => {
                    if (e.key === 'Enter' && !e.shiftKey) {
                        e.preventDefault();
                        if (!isProcessing) handleExecute();
                    }
                 }}
                 placeholder="INPUT QUERY FOR VERIFICATION..."
                 disabled={isProcessing}
                 className="w-full h-full bg-zinc-900/50 border border-zinc-800 text-veritas-cyan font-mono text-sm p-3 focus:outline-none focus:border-veritas-cyan/50 resize-none placeholder:text-zinc-700"
               />
               <div className="absolute top-0 right-0 p-1">
                 <div className="w-2 h-2 border border-zinc-600"></div>
               </div>
             </div>
             <button
                onClick={handleExecute}
                disabled={isProcessing || !userPrompt.trim()}
                className="h-full px-8 bg-veritas-cyan/10 border border-veritas-cyan text-veritas-cyan font-mono font-bold tracking-wider hover:bg-veritas-cyan hover:text-black transition-all disabled:opacity-30 disabled:cursor-not-allowed"
             >
                {isProcessing ? 'PROCESSING' : 'EXECUTE'}
             </button>
          </div>
        </section>
      </main>

      {/* MODAL */}
      {isEditingConfig && (
        <ConfigEditor config={config} onSave={handleSaveConfig} onClose={() => setIsEditingConfig(false)} />
      )}
    </div>
  );
};

export default App;

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { SystemConfig, LogEntry, AgentConfig, ChatHistoryItem } from "../types";
import { generateSystemInstruction, ANALYST_PROMPT, SKEPTIC_PROMPT, JUDGE_PROMPT, META_INSPECTION_PROMPT } from "./prompts";

// Schemas
const ANALYST_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    thought_process: { type: Type.STRING, description: "Hidden reasoning steps" },
    factual_answer: { type: Type.STRING, description: "The proposed truth" },
    confidence: { type: Type.NUMBER, description: "0-100 certainty score" },
  },
  required: ["thought_process", "factual_answer", "confidence"],
};

const SKEPTIC_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    analysis: { type: Type.STRING, description: "Critique of the input" },
    has_flaws: { type: Type.BOOLEAN, description: "True if errors exist" },
    flaws: { type: Type.ARRAY, items: { type: Type.STRING }, description: "List of specific errors" },
    correction: { type: Type.STRING, description: "Proposed fix" },
  },
  required: ["analysis", "has_flaws", "flaws", "correction"],
};

const JUDGE_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    debate_summary: { type: Type.STRING, description: "Brief recap of the argument" },
    final_verdict: { type: Type.STRING, description: "The absolute final answer for the user" },
    is_conclusive: { type: Type.BOOLEAN },
  },
  required: ["debate_summary", "final_verdict"],
};

const META_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    response: { type: Type.STRING, description: "The agent's explanation of its own state" },
    internal_state: { type: Type.STRING, description: "Technical status or mode description" }
  },
  required: ["response", "internal_state"]
};

const uuid = () => Math.random().toString(36).substring(2, 9);

export class MultiAgentService {
  private ai: GoogleGenAI;

  constructor(apiKey: string) {
    this.ai = new GoogleGenAI({ apiKey });
  }

  /**
   * Cleans raw model output (which might include markdown code blocks) and parses it.
   */
  private cleanAndParseJSON(text: string): any {
    try {
      // Remove markdown code blocks if present (e.g. ```json ... ```)
      const cleanText = text.replace(/```json\n?|\n?```/g, "").trim();
      return JSON.parse(cleanText);
    } catch (e) {
      console.error("JSON Parse Error. Raw text:", text);
      throw new Error("Failed to parse agent response. The agent may have deviated from the protocol.");
    }
  }

  private async callAgentJSON(
    model: string,
    systemPrompt: string,
    userPrompt: string,
    schema: Schema,
    useTools: boolean = false
  ): Promise<{ data: any; sources?: any[] }> {
    try {
      // Configuration for Gemini 3
      const config: any = {
        systemInstruction: systemPrompt,
        responseMimeType: "application/json",
        responseSchema: schema,
        temperature: 0.1, // Strict logic for truth
      };

      // Add Search Tool & Thinking Config
      if (useTools) {
        config.tools = [{ googleSearch: {} }];
        // Increased thinking budget for Pro model to ensure deep reasoning
        config.thinkingConfig = { thinkingBudget: 2048 }; 
      }

      const response = await this.ai.models.generateContent({
        model,
        contents: userPrompt,
        config,
      });

      const text = response.text;
      const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;

      if (!text) throw new Error("Empty response from AI");

      return {
        data: this.cleanAndParseJSON(text),
        sources: groundingChunks
      };
    } catch (error) {
      console.error("Agent Execution Failed:", error);
      throw error;
    }
  }

  public async interrogateAgent(
    targetAgentRole: string,
    userQuery: string,
    config: SystemConfig,
    chatHistory: ChatHistoryItem[],
    onLog: (log: LogEntry) => void
  ): Promise<string> {
    const modelName = 'gemini-3-flash-preview'; // Flash is sufficient for meta-analysis
    const agent = config.agents.find(a => a.role === targetAgentRole);

    if (!agent) throw new Error(`Agent ${targetAgentRole} not found`);

    // Format previous history
    let contextBlock = "";
    if (chatHistory.length > 0) {
        contextBlock = "PREVIOUS SESSION LOGS:\n" + chatHistory.map(turn => 
            `${turn.role === 'user' ? 'USER' : 'SYSTEM'}: ${turn.content}`
        ).join("\n") + "\n\n";
    }

    onLog(this.createLog(agent.role, agent.name, "Running self-diagnostic...", true));

    const response = await this.callAgentJSON(
      modelName,
      generateSystemInstruction(agent, config),
      META_INSPECTION_PROMPT(contextBlock, userQuery),
      META_SCHEMA,
      false
    );

    onLog(this.createLog(
      agent.role, 
      agent.name, 
      response.data.response, 
      false, 
      { thought_process: response.data.internal_state }
    ));

    return response.data.response;
  }

  public async runReasoningChain(
    userPrompt: string,
    config: SystemConfig,
    chatHistory: ChatHistoryItem[],
    onLog: (log: LogEntry) => void,
    onRoundUpdate?: (round: number) => void
  ): Promise<string> {
    // Upgraded to PRO model for complex STEM/Reasoning tasks
    const modelName = 'gemini-3-pro-preview';
    const analyst = config.agents.find(a => a.role === 'analyst')!;
    const skeptic = config.agents.find(a => a.role === 'skeptic')!;
    const judge = config.agents.find(a => a.role === 'judge')!;

    // Format previous history
    let contextBlock = "";
    if (chatHistory.length > 0) {
        contextBlock = "PREVIOUS CONVERSATION CONTEXT:\n" + chatHistory.map(turn => 
            `${turn.role === 'user' ? 'USER' : 'VERITAS_SYSTEM'}: ${turn.content}`
        ).join("\n") + "\n\n";
    }

    // Initialize the Debate Transcript (The "Room") with context + new prompt
    let debateTranscript = `${contextBlock}CURRENT USER QUERY: "${userPrompt}"\n`;
    let currentDraft = "";
    let consensus = false;
    let roundsExecuted = 0;

    // --- ANALYST (Round 0) ---
    onLog(this.createLog('analyst', analyst.name, "Initializing deep scan & logic vectors...", true));

    // Analyst gets Search Tools & Thinking
    const analystRes = await this.callAgentJSON(
      modelName,
      generateSystemInstruction(analyst, config),
      ANALYST_PROMPT(debateTranscript),
      ANALYST_SCHEMA,
      true // Enable Search & Thinking
    );

    currentDraft = analystRes.data.factual_answer;
    debateTranscript += `\n[${analyst.name}]: ${currentDraft}\n(Confidence: ${analystRes.data.confidence}%)\n`;

    onLog(this.createLog(
      'analyst', 
      analyst.name, 
      analystRes.data.factual_answer, 
      false, 
      analystRes.data,
      analystRes.sources
    ));

    // --- DEBATE LOOP ---
    for (let i = 1; i <= config.max_rounds; i++) {
      roundsExecuted = i; // Tracking the turn counter
      if (onRoundUpdate) onRoundUpdate(i);

      // SKEPTIC
      onLog(this.createLog('skeptic', skeptic.name, `Running integrity check (Cycle ${i})...`, true));

      // Skeptic gets Search Tools to verify claims
      const skepticRes = await this.callAgentJSON(
        modelName,
        generateSystemInstruction(skeptic, config),
        SKEPTIC_PROMPT(debateTranscript, currentDraft),
        SKEPTIC_SCHEMA,
        true // Enable Tools for Verification
      );

      debateTranscript += `\n[${skeptic.name}]: ${skepticRes.data.analysis}\nFlaws: ${skepticRes.data.flaws.join(", ")}\n`;

      const skepticLogContent = skepticRes.data.has_flaws 
        ? `OBJECTION: ${skepticRes.data.analysis}`
        : `AGREEMENT: ${skepticRes.data.analysis}`;

      onLog(this.createLog(
        'skeptic', 
        skeptic.name, 
        skepticLogContent, 
        false, 
        skepticRes.data,
        skepticRes.sources // Log Skeptic's verification sources
      ));

      if (!skepticRes.data.has_flaws) {
        consensus = true;
        break;
      }

      if (i === config.max_rounds) break;

      // ANALYST REBUTTAL
      onLog(this.createLog('analyst', analyst.name, "Processing critique & refining...", true));

      const rebuttalRes = await this.callAgentJSON(
        modelName,
        generateSystemInstruction(analyst, config),
        `CRITIQUE RECEIVED: ${skepticRes.data.analysis}\nSUGGESTED CORRECTION: ${skepticRes.data.correction}\n\nRefine your answer.`,
        ANALYST_SCHEMA,
        true // Enable Search & Thinking for rebuttal
      );

      currentDraft = rebuttalRes.data.factual_answer;
      debateTranscript += `\n[${analyst.name} (Refined)]: ${currentDraft}\n`;
      onLog(this.createLog(
        'analyst', 
        analyst.name, 
        currentDraft, 
        false, 
        rebuttalRes.data,
        rebuttalRes.sources
      ));
    }

    // --- JUDGE ---
    onLog(this.createLog('judge', judge.name, "Compiling final verdict...", true));

    // Passing the turn counter (roundsExecuted) to the Judge Prompt for Fallback Logic
    const judgeRes = await this.callAgentJSON(
      modelName,
      generateSystemInstruction(judge, config),
      JUDGE_PROMPT(debateTranscript, consensus, roundsExecuted),
      JUDGE_SCHEMA
    );

    onLog(this.createLog(
      'judge', 
      judge.name, 
      judgeRes.data.final_verdict, 
      false, 
      judgeRes.data
    ));

    return judgeRes.data.final_verdict;
  }

  private createLog(
    role: any, 
    name: string, 
    content: string, 
    isThinking: boolean, 
    metadata?: any, 
    sources?: any[]
  ): LogEntry {
    return {
      id: uuid(),
      agentRole: role,
      agentName: name,
      content,
      isThinking,
      timestamp: Date.now(),
      metadata,
      sources
    };
  }
}

import { useState, useCallback } from 'react';
import { SystemConfig, LogEntry, ProcessState, ChatHistoryItem } from '../types';
import { MultiAgentService } from '../services/geminiService';

export const useReasoningEngine = (config: SystemConfig) => {
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [processState, setProcessState] = useState<ProcessState>(ProcessState.IDLE);
  const [finalResult, setFinalResult] = useState<string | null>(null);
  const [chatHistory, setChatHistory] = useState<ChatHistoryItem[]>([]);
  const [currentRound, setCurrentRound] = useState<number>(0);

  const startReasoning = useCallback(async (userPrompt: string) => {
    const apiKey = process.env.API_KEY;
    if (!apiKey) {
      console.error("API Key missing");
      return;
    }

    // Reset UI state for new operation
    setProcessState(ProcessState.ANALYZING);
    setFinalResult(null);
    setCurrentRound(0);

    // Add visual separator for new turn if not the first one
    if (logs.length > 0) {
      setLogs(prev => [...prev, {
        id: `sep-${Date.now()}`,
        agentRole: 'system',
        agentName: 'SYSTEM',
        content: '-------------------------------- NEW SESSION TURN --------------------------------',
        timestamp: Date.now()
      }]);
    }

    const service = new MultiAgentService(apiKey);

    // Check for Meta-Interrogation Command (e.g., "@DATA_CORE_01: status report" or "@Analyst: explain")
    const interrogationMatch = userPrompt.match(/^@([^:]+):(.+)$/);

    try {
      if (interrogationMatch) {
         const targetIdentifier = interrogationMatch[1].trim();
         const query = interrogationMatch[2].trim();

         // Find agent by Name OR Role (case-insensitive)
         const agent = config.agents.find(a => 
            a.name.toLowerCase() === targetIdentifier.toLowerCase() || 
            a.role.toLowerCase() === targetIdentifier.toLowerCase()
         );

         if (agent) {
            // META INTERROGATION MODE
            const result = await service.interrogateAgent(
                agent.role,
                query,
                config,
                chatHistory,
                (log) => {
                    setLogs(prev => {
                        // Remove previous thinking log from same agent to avoid duplicates
                        const filtered = prev.filter(l => !(l.agentRole === log.agentRole && l.isThinking));
                        return [...filtered, log];
                    });
                }
            );
             setFinalResult(result);
             setProcessState(ProcessState.COMPLETE);
             return;
         }
      }

      // STANDARD REASONING CHAIN
      const result = await service.runReasoningChain(
        userPrompt, 
        config,
        chatHistory, 
        (log) => {
          setLogs(prev => {
            // Remove previous thinking log from same agent
            const filtered = prev.filter(l => !(l.agentRole === log.agentRole && l.isThinking));
            return [...filtered, log];
          });

          if (log.isThinking) {
             const stateMap: Record<string, ProcessState> = {
               'analyst': ProcessState.ANALYZING,
               'skeptic': ProcessState.AUDITING,
               'judge': ProcessState.JUDGING
             };
             if (stateMap[log.agentRole]) setProcessState(stateMap[log.agentRole]);
          }
        },
        (round) => {
            setCurrentRound(round);
        }
      );

      setFinalResult(result);
      setProcessState(ProcessState.COMPLETE);

      // Update Short-Term Memory
      setChatHistory(prev => [
        ...prev,
        { role: 'user', content: userPrompt },
        { role: 'model', content: result }
      ]);

    } catch (e) {
      console.error(e);
      setProcessState(ProcessState.ERROR);
      setLogs(prev => [...prev, {
        id: 'ERR', 
        agentRole: 'judge', 
        agentName: 'SYSTEM', 
        content: 'CRITICAL FAILURE', 
        timestamp: Date.now()
      }]);
    }
  }, [config, chatHistory, logs.length]); 

  const clearMemory = useCallback(() => {
    setChatHistory([]);
    setLogs([]);
    setFinalResult(null);
    setProcessState(ProcessState.IDLE);
    setCurrentRound(0);
  }, []);

  return {
    logs,
    processState,
    finalResult,
    currentRound,
    startReasoning,
    clearMemory
  };
};

import { useCallback, useRef, useState, useEffect } from 'react';

export const useSoundFX = () => {
  const audioContextRef = useRef<AudioContext | null>(null);
  const gainNodeRef = useRef<GainNode | null>(null);
  // Persist mute state
  const [isMuted, setIsMuted] = useState(() => {
    try {
      return localStorage.getItem('veritas_sound_muted') === 'true';
    } catch {
      return false;
    }
  });

  const toggleMute = useCallback(() => {
    setIsMuted(prev => {
      const newState = !prev;
      localStorage.setItem('veritas_sound_muted', String(newState));
      return newState;
    });
  }, []);

  const initAudio = useCallback(() => {
    if (!audioContextRef.current) {
      const AudioContextClass = (window.AudioContext || (window as any).webkitAudioContext);
      audioContextRef.current = new AudioContextClass();
      gainNodeRef.current = audioContextRef.current.createGain();
      gainNodeRef.current.connect(audioContextRef.current.destination);
    }
    if (audioContextRef.current.state === 'suspended') {
      audioContextRef.current.resume();
    }
    // Update gain based on mute state
    if (gainNodeRef.current) {
      gainNodeRef.current.gain.value = isMuted ? 0 : 0.1;
    }
  }, [isMuted]);

  // Sync gain with mute state changes
  useEffect(() => {
    if (gainNodeRef.current) {
      gainNodeRef.current.gain.value = isMuted ? 0 : 0.1;
    }
  }, [isMuted]);

  const playOscillator = (
    freq: number, 
    type: OscillatorType, 
    duration: number, 
    startTime: number = 0,
    vol: number = 0.1
  ) => {
    if (isMuted || !audioContextRef.current || !gainNodeRef.current) return;

    const osc = audioContextRef.current.createOscillator();
    const gain = audioContextRef.current.createGain();

    osc.type = type;
    osc.frequency.setValueAtTime(freq, audioContextRef.current.currentTime + startTime);

    gain.gain.setValueAtTime(vol, audioContextRef.current.currentTime + startTime);
    gain.gain.exponentialRampToValueAtTime(0.01, audioContextRef.current.currentTime + startTime + duration);

    osc.connect(gain);
    gain.connect(gainNodeRef.current);

    osc.start(audioContextRef.current.currentTime + startTime);
    osc.stop(audioContextRef.current.currentTime + startTime + duration);
  };

  const playBlip = useCallback(() => {
    initAudio();
    playOscillator(1200, 'sine', 0.05);
  }, [initAudio, isMuted]);

  const playClick = useCallback(() => {
    initAudio();
    playOscillator(800, 'square', 0.01, 0, 0.05);
  }, [initAudio, isMuted]);

  const playActivate = useCallback(() => {
    initAudio();
    playOscillator(220, 'sawtooth', 0.3, 0, 0.05);
    playOscillator(440, 'sine', 0.3, 0.1, 0.05);
    playOscillator(880, 'square', 0.4, 0.2, 0.03);
  }, [initAudio, isMuted]);

  const playDataStream = useCallback(() => {
    initAudio();
    // Random data noise
    for(let i=0; i<5; i++) {
        playOscillator(1000 + Math.random() * 2000, 'square', 0.02, i * 0.03, 0.02);
    }
  }, [initAudio, isMuted]);

  const playVerdict = useCallback(() => {
    initAudio();
    const root = 261.63; // C4
    playOscillator(root, 'triangle', 1.5, 0, 0.1);
    playOscillator(root * 1.25, 'triangle', 1.5, 0.1, 0.1); // E4
    playOscillator(root * 1.5, 'triangle', 1.5, 0.2, 0.1); // G4
    playOscillator(root * 2, 'sine', 2.0, 0.3, 0.05); // C5
  }, [initAudio, isMuted]);

  const playError = useCallback(() => {
    initAudio();
    playOscillator(150, 'sawtooth', 0.4, 0, 0.1);
    playOscillator(140, 'sawtooth', 0.4, 0, 0.1);
  }, [initAudio, isMuted]);

  return {
    isMuted,
    toggleMute,
    playBlip,
    playClick,
    playActivate,
    playDataStream,
    playVerdict,
    playError
  };
};

