import { GoogleGenAI, Type, Schema } from "@google/genai";
import { SystemConfig, LogEntry, AgentConfig, ChatHistoryItem } from "../types";
import { generateSystemInstruction, ANALYST_PROMPT, SKEPTIC_PROMPT, JUDGE_PROMPT, META_INSPECTION_PROMPT } from "./prompts";

// Schemas
const ANALYST_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    thought_process: { type: Type.STRING, description: "Hidden reasoning steps" },
    factual_answer: { type: Type.STRING, description: "The proposed truth" },
    confidence: { type: Type.NUMBER, description: "0-100 certainty score" },
  },
  required: ["thought_process", "factual_answer", "confidence"],
};

const SKEPTIC_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    analysis: { type: Type.STRING, description: "Critique of the input" },
    has_flaws: { type: Type.BOOLEAN, description: "True if errors exist" },
    flaws: { type: Type.ARRAY, items: { type: Type.STRING }, description: "List of specific errors" },
    correction: { type: Type.STRING, description: "Proposed fix" },
  },
  required: ["analysis", "has_flaws", "flaws", "correction"],
};

const JUDGE_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    debate_summary: { type: Type.STRING, description: "Brief recap of the argument" },
    final_verdict: { type: Type.STRING, description: "The absolute final answer for the user" },
    is_conclusive: { type: Type.BOOLEAN },
  },
  required: ["debate_summary", "final_verdict"],
};

const META_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    response: { type: Type.STRING, description: "The agent's explanation of its own state" },
    internal_state: { type: Type.STRING, description: "Technical status or mode description" }
  },
  required: ["response", "internal_state"]
};

const uuid = () => Math.random().toString(36).substring(2, 9);

interface GenerationOptions {
  useTools?: boolean;
  temperature?: number;
  topK?: number;
  topP?: number;
}

export class MultiAgentService {
  private ai: GoogleGenAI;

  constructor(apiKey: string) {
    this.ai = new GoogleGenAI({ apiKey });
  }

  /**
   * Cleans raw model output (which might include markdown code blocks) and parses it.
   */
  private cleanAndParseJSON(text: string): any {
    try {
      // Remove markdown code blocks if present (e.g. ```json ... ```)
      const cleanText = text.replace(/```json\n?|\n?```/g, "").trim();
      return JSON.parse(cleanText);
    } catch (e) {
      console.error("JSON Parse Error. Raw text:", text);
      throw new Error("Failed to parse agent response. The agent may have deviated from the protocol.");
    }
  }

  private async callAgentJSON(
    model: string,
    systemPrompt: string,
    userPrompt: string,
    schema: Schema,
    options: GenerationOptions = {}
  ): Promise<{ data: any; sources?: any[] }> {
    try {
      // Base Configuration for Gemini 3
      const config: any = {
        systemInstruction: systemPrompt,
        responseMimeType: "application/json",
        responseSchema: schema,
        temperature: options.temperature ?? 0.1, // Use override or strict default
      };

      // Apply overrides if present
      if (options.topK !== undefined) config.topK = options.topK;
      if (options.topP !== undefined) config.topP = options.topP;

      // Add Search Tool & Thinking Config
      if (options.useTools) {
        config.tools = [{ googleSearch: {} }];
        // Increased thinking budget for Pro model to ensure deep reasoning
        config.thinkingConfig = { thinkingBudget: 2048 }; 
      }

      const response = await this.ai.models.generateContent({
        model,
        contents: userPrompt,
        config,
      });

      const text = response.text;
      const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;

      if (!text) throw new Error("Empty response from AI");

      return {
        data: this.cleanAndParseJSON(text),
        sources: groundingChunks
      };
    } catch (error) {
      console.error("Agent Execution Failed:", error);
      throw error;
    }
  }

  public async interrogateAgent(
    targetAgentRole: string,
    userQuery: string,
    config: SystemConfig,
    chatHistory: ChatHistoryItem[],
    sessionLogs: LogEntry[],
    onLog: (log: LogEntry) => void
  ): Promise<string> {
    const modelName = 'gemini-3-flash-preview'; // Flash is sufficient for meta-analysis
    const agent = config.agents.find(a => a.role === targetAgentRole);

    if (!agent) throw new Error(`Agent ${targetAgentRole} not found`);

    // Build rich context from session logs including hidden metadata (thoughts, flaws)
    const logContext = sessionLogs.slice(-40).map(l => {
        let details = "";
        if (l.metadata) {
             if (l.metadata.thought_process) details += `\n   [INTERNAL THOUGHT]: ${l.metadata.thought_process}`;
             if (l.metadata.flaws && l.metadata.flaws.length > 0) details += `\n   [FLAWS FLAGGED]: ${l.metadata.flaws.join(' | ')}`;
             if (l.metadata.confidence) details += ` [Confidence: ${l.metadata.confidence}%]`;
        }
        return `[${new Date(l.timestamp).toLocaleTimeString()}] ${l.agentName} (${l.agentRole}): ${l.content}${details}`;
    }).join('\n');

    let contextBlock = "=== SYSTEM INTERNAL LOGS (MOST RECENT) ===\n" + logContext + "\n\n";

    if (chatHistory.length > 0) {
        contextBlock += "=== USER CHAT HISTORY ===\n" + chatHistory.map(turn => 
            `${turn.role === 'user' ? 'USER' : 'SYSTEM'}: ${turn.content}`
        ).join("\n") + "\n\n";
    }

    onLog(this.createLog(agent.role, agent.name, "Running self-diagnostic...", true));

    const response = await this.callAgentJSON(
      modelName,
      generateSystemInstruction(agent, config),
      META_INSPECTION_PROMPT(contextBlock, userQuery),
      META_SCHEMA,
      {
        useTools: false,
        temperature: agent.temperature,
        topK: agent.topK,
        topP: agent.topP
      }
    );

    onLog(this.createLog(
      agent.role, 
      agent.name, 
      response.data.response, 
      false, 
      { thought_process: response.data.internal_state }
    ));

    return response.data.response;
  }

  public async runReasoningChain(
    userPrompt: string,
    config: SystemConfig,
    chatHistory: ChatHistoryItem[],
    onLog: (log: LogEntry) => void,
    onRoundUpdate?: (round: number) => void
  ): Promise<string> {
    // Upgraded to PRO model for complex STEM/Reasoning tasks
    const modelName = 'gemini-3-pro-preview';
    const analyst = config.agents.find(a => a.role === 'analyst')!;
    const skeptic = config.agents.find(a => a.role === 'skeptic')!;
    const judge = config.agents.find(a => a.role === 'judge')!;

    // Format previous history
    let contextBlock = "";
    if (chatHistory.length > 0) {
        contextBlock = "PREVIOUS CONVERSATION CONTEXT:\n" + chatHistory.map(turn => 
            `${turn.role === 'user' ? 'USER' : 'VERITAS_SYSTEM'}: ${turn.content}`
        ).join("\n") + "\n\n";
    }

    // Initialize the Debate Transcript (The "Room") with context + new prompt
    let debateTranscript = `${contextBlock}CURRENT USER QUERY: "${userPrompt}"\n`;
    let currentDraft = "";
    let consensus = false;
    let roundsExecuted = 0;

    // --- ANALYST (Round 0) ---
    onLog(this.createLog('analyst', analyst.name, "Initializing deep scan & logic vectors...", true));

    // Analyst gets Search Tools & Thinking
    const analystRes = await this.callAgentJSON(
      modelName,
      generateSystemInstruction(analyst, config),
      ANALYST_PROMPT(debateTranscript),
      ANALYST_SCHEMA,
      {
        useTools: true,
        temperature: analyst.temperature,
        topK: analyst.topK,
        topP: analyst.topP
      }
    );

    currentDraft = analystRes.data.factual_answer;
    debateTranscript += `\n[${analyst.name}]: ${currentDraft}\n(Confidence: ${analystRes.data.confidence}%)\n`;

    onLog(this.createLog(
      'analyst', 
      analyst.name, 
      analystRes.data.factual_answer, 
      false, 
      analystRes.data,
      analystRes.sources
    ));

    // --- DEBATE LOOP ---
    for (let i = 1; i <= config.max_rounds; i++) {
      roundsExecuted = i; // Tracking the turn counter
      if (onRoundUpdate) onRoundUpdate(i);

      // SKEPTIC
      onLog(this.createLog('skeptic', skeptic.name, `Running integrity check (Cycle ${i})...`, true));

      // Skeptic gets Search Tools to verify claims
      const skepticRes = await this.callAgentJSON(
        modelName,
        generateSystemInstruction(skeptic, config),
        SKEPTIC_PROMPT(debateTranscript, currentDraft),
        SKEPTIC_SCHEMA,
        {
            useTools: true,
            temperature: skeptic.temperature,
            topK: skeptic.topK,
            topP: skeptic.topP
        }
      );

      debateTranscript += `\n[${skeptic.name}]: ${skepticRes.data.analysis}\nFlaws: ${skepticRes.data.flaws.join(", ")}\n`;

      const skepticLogContent = skepticRes.data.has_flaws 
        ? `OBJECTION: ${skepticRes.data.analysis}`
        : `AGREEMENT: ${skepticRes.data.analysis}`;

      onLog(this.createLog(
        'skeptic', 
        skeptic.name, 
        skepticLogContent, 
        false, 
        skepticRes.data,
        skepticRes.sources // Log Skeptic's verification sources
      ));

      if (!skepticRes.data.has_flaws) {
        consensus = true;
        break;
      }

      if (i === config.max_rounds) break;

      // ANALYST REBUTTAL
      onLog(this.createLog('analyst', analyst.name, "Processing critique & refining...", true));

      const rebuttalRes = await this.callAgentJSON(
        modelName,
        generateSystemInstruction(analyst, config),
        `CRITIQUE RECEIVED: ${skepticRes.data.analysis}\nSUGGESTED CORRECTION: ${skepticRes.data.correction}\n\nRefine your answer.`,
        ANALYST_SCHEMA,
        {
            useTools: true,
            temperature: analyst.temperature,
            topK: analyst.topK,
            topP: analyst.topP
        }
      );

      currentDraft = rebuttalRes.data.factual_answer;
      debateTranscript += `\n[${analyst.name} (Refined)]: ${currentDraft}\n`;
      onLog(this.createLog(
        'analyst', 
        analyst.name, 
        currentDraft, 
        false, 
        rebuttalRes.data,
        rebuttalRes.sources
      ));
    }

    // --- JUDGE ---
    onLog(this.createLog('judge', judge.name, "Compiling final verdict...", true));

    // Passing the turn counter (roundsExecuted) to the Judge Prompt for Fallback Logic
    const judgeRes = await this.callAgentJSON(
      modelName,
      generateSystemInstruction(judge, config),
      JUDGE_PROMPT(debateTranscript, consensus, roundsExecuted),
      JUDGE_SCHEMA,
      {
          useTools: false,
          temperature: judge.temperature,
          topK: judge.topK,
          topP: judge.topP
      }
    );

    onLog(this.createLog(
      'judge', 
      judge.name, 
      judgeRes.data.final_verdict, 
      false, 
      judgeRes.data
    ));

    return judgeRes.data.final_verdict;
  }

  private createLog(
    role: any, 
    name: string, 
    content: string, 
    isThinking: boolean, 
    metadata?: any, 
    sources?: any[]
  ): LogEntry {
    return {
      id: uuid(),
      agentRole: role,
      agentName: name,
      content,
      isThinking,
      timestamp: Date.now(),
      metadata,
      sources
    };
  }
}

import React, { useState, useEffect } from 'react';
import { SystemConfig } from '../types';
import { PRESETS } from '../constants';

interface ConfigEditorProps {
  config: SystemConfig;
  onSave: (newConfig: SystemConfig) => void;
  onClose: () => void;
}

const CUSTOM_PRESETS_KEY = 'veritas_custom_presets';

export const ConfigEditor: React.FC<ConfigEditorProps> = ({ config, onSave, onClose }) => {
  const [jsonText, setJsonText] = useState(JSON.stringify(config, null, 2));
  const [error, setError] = useState<string | null>(null);
  const [customPresets, setCustomPresets] = useState<Record<string, SystemConfig>>({});
  const [newPresetName, setNewPresetName] = useState('');

  // Load custom presets on mount
  useEffect(() => {
    try {
      const stored = localStorage.getItem(CUSTOM_PRESETS_KEY);
      if (stored) {
        setCustomPresets(JSON.parse(stored));
      }
    } catch (e) {
      console.error("Failed to load custom presets", e);
    }
  }, []);

  const handleApply = () => {
    try {
      const parsed = JSON.parse(jsonText);
      // Basic validation
      if (!parsed.agents || !Array.isArray(parsed.agents) || parsed.agents.length !== 3) {
        throw new Error("Configuration must include exactly 3 agents.");
      }
      onSave(parsed);
      onClose();
    } catch (e: any) {
      setError(e.message || "Invalid JSON");
    }
  };

  const handleLoadPreset = (presetConfig: SystemConfig) => {
    setJsonText(JSON.stringify(presetConfig, null, 2));
    setError(null);
  };

  const handleSaveCustomPreset = () => {
    try {
      if (!newPresetName.trim()) throw new Error("Preset name required");

      const parsed = JSON.parse(jsonText);
      // Basic validation
      if (!parsed.agents || !Array.isArray(parsed.agents) || parsed.agents.length !== 3) {
        throw new Error("Invalid configuration structure. Must have 3 agents.");
      }

      // Store in Upper Case for consistency
      const key = newPresetName.trim().toUpperCase().replace(/\s+/g, '_');

      const updatedPresets = { ...customPresets, [key]: parsed };
      setCustomPresets(updatedPresets);
      localStorage.setItem(CUSTOM_PRESETS_KEY, JSON.stringify(updatedPresets));
      setNewPresetName('');
      setError(null); // Clear errors on success
    } catch (e: any) {
      setError(e.message || "Invalid JSON");
    }
  };

  const handleDeletePreset = (key: string, e: React.MouseEvent) => {
    e.stopPropagation();
    const updated = { ...customPresets };
    delete updated[key];
    setCustomPresets(updated);
    localStorage.setItem(CUSTOM_PRESETS_KEY, JSON.stringify(updated));
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/90 backdrop-blur-sm p-4">
      <div className="w-full max-w-6xl h-[85vh] bg-zinc-950 border border-zinc-700 shadow-2xl flex flex-col md:flex-row overflow-hidden">

        {/* SIDEBAR: PRESETS */}
        <div className="w-full md:w-64 bg-zinc-900 border-r border-zinc-800 flex flex-col min-h-[200px] md:min-h-0">
          <div className="p-3 border-b border-zinc-800 bg-zinc-950/50">
            <h3 className="text-zinc-500 font-mono text-xs uppercase tracking-widest">Load Preset</h3>
          </div>

          <div className="flex-1 overflow-y-auto p-2 space-y-4">
            {/* SYSTEM PRESETS */}
            <div>
              <div className="text-[10px] text-zinc-600 font-bold mb-2 px-2">SYSTEM DEFAULTS</div>
              <div className="space-y-1">
                {Object.entries(PRESETS).map(([key, val]) => (
                  <button
                    key={key}
                    onClick={() => handleLoadPreset(val as SystemConfig)}
                    className="w-full text-left px-3 py-2 text-xs font-mono text-zinc-400 hover:bg-zinc-800 hover:text-veritas-cyan transition-colors rounded-sm"
                  >
                    {key}
                  </button>
                ))}
              </div>
            </div>

            {/* CUSTOM PRESETS */}
            <div>
              <div className="text-[10px] text-zinc-600 font-bold mb-2 px-2">USER ARCHIVES</div>
              {Object.keys(customPresets).length === 0 && (
                 <div className="px-3 text-[10px] text-zinc-700 italic">No custom presets saved.</div>
              )}
              <div className="space-y-1">
                {Object.entries(customPresets).map(([key, val]) => (
                  <button
                    key={key}
                    onClick={() => handleLoadPreset(val as SystemConfig)}
                    className="w-full text-left px-3 py-2 text-xs font-mono text-zinc-300 hover:bg-zinc-800 hover:text-veritas-gold transition-colors rounded-sm flex justify-between group"
                  >
                    <span>{key}</span>
                    <span 
                      onClick={(e) => handleDeletePreset(key, e)}
                      className="text-zinc-600 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
                    >
                      ×
                    </span>
                  </button>
                ))}
              </div>
            </div>

             {/* SCHEMA DOCS */}
             <div className="border-t border-zinc-800 mt-2 pt-2">
               <div className="text-[10px] text-zinc-600 font-bold mb-2 px-2">SCHEMA REFERENCE</div>
               <div className="px-3 text-[10px] text-zinc-500 space-y-2 font-mono">
                  <p>You can override generation params per agent:</p>
                  <ul className="list-disc list-inside opacity-70">
                    <li><span className="text-veritas-cyan">temperature</span> (0.0 - 2.0)</li>
                    <li><span className="text-veritas-cyan">topK</span> (1 - 40)</li>
                    <li><span className="text-veritas-cyan">topP</span> (0.0 - 1.0)</li>
                  </ul>
                  <p className="text-[9px] italic opacity-50">Example: "temperature": 0.8</p>
               </div>
            </div>

          </div>
        </div>

        {/* MAIN EDITOR AREA */}
        <div className="flex-1 flex flex-col h-full min-w-0">
          <div className="p-4 border-b border-zinc-800 flex justify-between items-center bg-zinc-950">
            <h2 className="text-veritas-cyan font-mono text-lg font-bold">SYSTEM_CONFIGURATION.JSON</h2>
            <button onClick={onClose} className="text-zinc-500 hover:text-white">ESC</button>
          </div>

          <div className="flex-1 relative bg-black/50">
             <textarea
              value={jsonText}
              onChange={(e) => setJsonText(e.target.value)}
              className="w-full h-full bg-transparent text-zinc-300 font-mono text-sm p-4 resize-none focus:outline-none focus:ring-1 focus:ring-veritas-cyan/30"
              spellCheck={false}
            />
          </div>

          <div className="p-4 border-t border-zinc-800 bg-zinc-900">
            {error && <div className="text-red-500 font-mono text-xs mb-3 border-l-2 border-red-500 pl-2 py-1 bg-red-950/20">{error}</div>}

            <div className="flex flex-col md:flex-row justify-between gap-4">

              {/* SAVE PRESET CONTROL */}
              <div className="flex gap-2 items-center flex-1">
                 <input 
                    type="text" 
                    value={newPresetName}
                    onChange={(e) => setNewPresetName(e.target.value)}
                    placeholder="NEW_PRESET_NAME"
                    className="bg-zinc-950 border border-zinc-700 text-xs font-mono text-white px-3 py-2 w-full md:w-48 focus:outline-none focus:border-zinc-500"
                 />
                 <button 
                   onClick={handleSaveCustomPreset}
                   className="whitespace-nowrap px-4 py-2 border border-zinc-700 text-zinc-400 font-mono text-xs hover:bg-zinc-800 hover:text-veritas-gold transition-colors"
                 >
                   SAVE PRESET
                 </button>
              </div>

              {/* ACTION BUTTONS */}
              <div className="flex gap-4 justify-end">
                <button 
                  onClick={onClose}
                  className="px-6 py-2 border border-zinc-600 text-zinc-400 font-mono text-xs hover:bg-zinc-800 transition-colors"
                >
                  CANCEL
                </button>
                <button 
                  onClick={handleApply}
                  className="px-6 py-2 bg-veritas-cyan/10 border border-veritas-cyan text-veritas-cyan font-mono text-xs font-bold hover:bg-veritas-cyan/20 transition-colors"
                >
                  COMPILE & APPLY
                </button>
              </div>
            </div>
          </div>
        </div>

      </div>
    </div>
  );
};

import { useState, useCallback } from 'react';
import { SystemConfig, LogEntry, ProcessState, ChatHistoryItem } from '../types';
import { MultiAgentService } from '../services/geminiService';

const uuid = () => Math.random().toString(36).substring(2, 9);

export const useReasoningEngine = (config: SystemConfig) => {
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [processState, setProcessState] = useState<ProcessState>(ProcessState.IDLE);
  const [finalResult, setFinalResult] = useState<string | null>(null);
  const [chatHistory, setChatHistory] = useState<ChatHistoryItem[]>([]);
  const [currentRound, setCurrentRound] = useState<number>(0);

  const startReasoning = useCallback(async (userPrompt: string) => {
    const apiKey = process.env.API_KEY;
    if (!apiKey) {
      console.error("API Key missing");
      return;
    }

    // Set processing state but DO NOT clear logs (enables continuous chat)
    setProcessState(ProcessState.ANALYZING);
    setFinalResult(null);
    setCurrentRound(0);

    // 1. Add User Input to Logs
    const userLog: LogEntry = {
        id: uuid(),
        agentRole: 'user',
        agentName: 'OPERATOR',
        content: userPrompt,
        timestamp: Date.now()
    };

    // Add separator if this isn't the first turn
    setLogs(prev => {
        const newLogs = [...prev];
        if (prev.length > 0) {
           newLogs.push({
             id: `sep-${Date.now()}`,
             agentRole: 'system',
             agentName: 'SYSTEM',
             content: 'NEW_CYCLE_INITIATED',
             timestamp: Date.now()
           });
        }
        return [...newLogs, userLog];
    });

    const service = new MultiAgentService(apiKey);

    try {
      // 2. Run Reasoning Chain with History
      const result = await service.runReasoningChain(
        userPrompt, 
        config,
        chatHistory,
        (log) => {
          setLogs(prev => {
            // Replace thinking logs for the same agent, append others
            const filtered = prev.filter(l => !(l.agentRole === log.agentRole && l.isThinking));
            return [...filtered, log];
          });

          if (log.isThinking) {
             const stateMap: Record<string, ProcessState> = {
               'analyst': ProcessState.ANALYZING,
               'skeptic': ProcessState.AUDITING,
               'judge': ProcessState.JUDGING
             };
             if (stateMap[log.agentRole]) setProcessState(stateMap[log.agentRole]);
          }
        },
        (round) => setCurrentRound(round)
      );

      setFinalResult(result);
      setProcessState(ProcessState.COMPLETE);

      // 3. Append Final Verdict to Logs
      const verdictLog: LogEntry = {
          id: uuid(),
          agentRole: 'verdict',
          agentName: 'VERITAS_FINAL',
          content: result,
          timestamp: Date.now()
      };
      setLogs(prev => [...prev, verdictLog]);

      // 4. Update Chat History Memory
      setChatHistory(prev => [
        ...prev,
        { role: 'user', content: userPrompt },
        { role: 'model', content: result }
      ]);

    } catch (e) {
      console.error(e);
      setProcessState(ProcessState.ERROR);
      setLogs(prev => [...prev, {
        id: 'ERR', 
        agentRole: 'judge', 
        agentName: 'SYSTEM', 
        content: 'CRITICAL FAILURE', 
        timestamp: Date.now()
      }]);
    }
  }, [config, chatHistory]);

  const clearMemory = useCallback(() => {
    setChatHistory([]);
    setLogs([]);
    setFinalResult(null);
    setProcessState(ProcessState.IDLE);
    setCurrentRound(0);
  }, []);

  return {
    logs,
    processState,
    finalResult,
    currentRound,
    chatHistory,
    startReasoning,
    clearMemory
  };
};

import { GoogleGenAI, Type, Schema } from "@google/genai";
import { SystemConfig, LogEntry, AgentConfig, ChatHistoryItem } from "../types";
import { generateSystemInstruction, ANALYST_PROMPT, SKEPTIC_PROMPT, JUDGE_PROMPT, META_INSPECTION_PROMPT } from "./prompts";

// Schemas
const ANALYST_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    thought_process: { type: Type.STRING, description: "Hidden reasoning steps" },
    factual_answer: { type: Type.STRING, description: "The proposed truth" },
    confidence: { type: Type.NUMBER, description: "0-100 certainty score" },
  },
  required: ["thought_process", "factual_answer", "confidence"],
};

const SKEPTIC_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    analysis: { type: Type.STRING, description: "Critique of the input" },
    has_flaws: { type: Type.BOOLEAN, description: "True if errors exist" },
    flaws: { type: Type.ARRAY, items: { type: Type.STRING }, description: "List of specific errors" },
    correction: { type: Type.STRING, description: "Proposed fix" },
  },
  required: ["analysis", "has_flaws", "flaws", "correction"],
};

const JUDGE_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    debate_summary: { type: Type.STRING, description: "Brief recap of the argument" },
    final_verdict: { type: Type.STRING, description: "The absolute final answer for the user" },
    is_conclusive: { type: Type.BOOLEAN },
  },
  required: ["debate_summary", "final_verdict"],
};

const META_SCHEMA: Schema = {
  type: Type.OBJECT,
  properties: {
    response: { type: Type.STRING, description: "The agent's explanation of its own state" },
    internal_state: { type: Type.STRING, description: "Technical status or mode description" }
  },
  required: ["response", "internal_state"]
};

const uuid = () => Math.random().toString(36).substring(2, 9);

interface GenerationOptions {
  useTools?: boolean;
  temperature?: number;
  topK?: number;
  topP?: number;
}

export class MultiAgentService {
  private ai: GoogleGenAI;

  constructor(apiKey: string) {
    this.ai = new GoogleGenAI({ apiKey });
  }

  /**
   * Cleans raw model output (which might include markdown code blocks) and parses it.
   */
  private cleanAndParseJSON(text: string): any {
    try {
      // Remove markdown code blocks if present (e.g. ```json ... ```)
      const cleanText = text.replace(/```json\n?|\n?```/g, "").trim();
      return JSON.parse(cleanText);
    } catch (e) {
      console.error("JSON Parse Error. Raw text:", text);
      throw new Error("Failed to parse agent response. The agent may have deviated from the protocol.");
    }
  }

  private async callAgentJSON(
    model: string,
    systemPrompt: string,
    userPrompt: string,
    schema: Schema,
    options: GenerationOptions = {}
  ): Promise<{ data: any; sources?: any[] }> {
    try {
      // Base Configuration for Gemini 3
      const config: any = {
        systemInstruction: systemPrompt,
        responseMimeType: "application/json",
        responseSchema: schema,
        temperature: options.temperature ?? 0.1, // Use override or strict default
      };

      // Apply overrides if present
      if (options.topK !== undefined) config.topK = options.topK;
      if (options.topP !== undefined) config.topP = options.topP;

      // Add Search Tool & Thinking Config
      if (options.useTools) {
        config.tools = [{ googleSearch: {} }];
        // Increased thinking budget for Pro model to ensure deep reasoning
        config.thinkingConfig = { thinkingBudget: 2048 }; 
      }

      const response = await this.ai.models.generateContent({
        model,
        contents: userPrompt,
        config,
      });

      const text = response.text;
      const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;

      if (!text) throw new Error("Empty response from AI");

      return {
        data: this.cleanAndParseJSON(text),
        sources: groundingChunks
      };
    } catch (error) {
      console.error("Agent Execution Failed:", error);
      throw error;
    }
  }

  public async interrogateAgent(
    targetAgentRole: string,
    userQuery: string,
    config: SystemConfig,
    chatHistory: ChatHistoryItem[],
    sessionLogs: LogEntry[],
    onLog: (log: LogEntry) => void
  ): Promise<string> {
    const modelName = 'gemini-3-flash-preview'; // Flash is sufficient for meta-analysis
    const agent = config.agents.find(a => a.role === targetAgentRole);

    if (!agent) throw new Error(`Agent ${targetAgentRole} not found`);

    // Build rich context from session logs including hidden metadata (thoughts, flaws)
    const logContext = sessionLogs.slice(-40).map(l => {
        let details = "";
        if (l.metadata) {
             if (l.metadata.thought_process) details += `\n   [INTERNAL THOUGHT]: ${l.metadata.thought_process}`;
             if (l.metadata.flaws && l.metadata.flaws.length > 0) details += `\n   [FLAWS FLAGGED]: ${l.metadata.flaws.join(' | ')}`;
             if (l.metadata.confidence) details += ` [Confidence: ${l.metadata.confidence}%]`;
        }
        return `[${new Date(l.timestamp).toLocaleTimeString()}] ${l.agentName} (${l.agentRole}): ${l.content}${details}`;
    }).join('\n');

    let contextBlock = "=== SYSTEM INTERNAL LOGS (MOST RECENT) ===\n" + logContext + "\n\n";

    if (chatHistory.length > 0) {
        contextBlock += "=== USER CHAT HISTORY ===\n" + chatHistory.map(turn => 
            `${turn.role === 'user' ? 'USER' : 'SYSTEM'}: ${turn.content}`
        ).join("\n") + "\n\n";
    }

    onLog(this.createLog(agent.role, agent.name, "Running self-diagnostic...", true));

    const response = await this.callAgentJSON(
      modelName,
      generateSystemInstruction(agent, config),
      META_INSPECTION_PROMPT(contextBlock, userQuery),
      META_SCHEMA,
      {
        useTools: false,
        temperature: agent.temperature,
        topK: agent.topK,
        topP: agent.topP
      }
    );

    onLog(this.createLog(
      agent.role, 
      agent.name, 
      response.data.response, 
      false, 
      { thought_process: response.data.internal_state }
    ));

    return response.data.response;
  }

  public async runReasoningChain(
    userPrompt: string,
    config: SystemConfig,
    chatHistory: ChatHistoryItem[],
    onLog: (log: LogEntry) => void,
    onRoundUpdate?: (round: number) => void
  ): Promise<string> {
    // Upgraded to PRO model for complex STEM/Reasoning tasks
    const modelName = 'gemini-3-pro-preview';
    const analyst = config.agents.find(a => a.role === 'analyst')!;
    const skeptic = config.agents.find(a => a.role === 'skeptic')!;
    const judge = config.agents.find(a => a.role === 'judge')!;

    // Format previous history
    let contextBlock = "";
    if (chatHistory.length > 0) {
        contextBlock = "PREVIOUS CONVERSATION CONTEXT:\n" + chatHistory.map(turn => 
            `${turn.role === 'user' ? 'USER' : 'VERITAS_SYSTEM'}: ${turn.content}`
        ).join("\n") + "\n\n";
    }

    // Initialize the Debate Transcript (The "Room") with context + new prompt
    let debateTranscript = `${contextBlock}CURRENT USER QUERY: "${userPrompt}"\n`;
    let currentDraft = "";
    let consensus = false;
    let roundsExecuted = 0;

    // --- ANALYST (Round 0) ---
    onLog(this.createLog('analyst', analyst.name, "Initializing deep scan & logic vectors...", true));

    // Analyst gets Search Tools & Thinking
    const analystRes = await this.callAgentJSON(
      modelName,
      generateSystemInstruction(analyst, config),
      ANALYST_PROMPT(debateTranscript),
      ANALYST_SCHEMA,
      {
        useTools: true,
        temperature: analyst.temperature,
        topK: analyst.topK,
        topP: analyst.topP
      }
    );

    currentDraft = analystRes.data.factual_answer;
    debateTranscript += `\n[${analyst.name}]: ${currentDraft}\n(Confidence: ${analystRes.data.confidence}%)\n`;

    onLog(this.createLog(
      'analyst', 
      analyst.name, 
      analystRes.data.factual_answer, 
      false, 
      analystRes.data,
      analystRes.sources
    ));

    // --- DEBATE LOOP ---
    for (let i = 1; i <= config.max_rounds; i++) {
      roundsExecuted = i; // Tracking the turn counter
      if (onRoundUpdate) onRoundUpdate(i);

      // SKEPTIC
      onLog(this.createLog('skeptic', skeptic.name, `Running integrity check (Cycle ${i})...`, true));

      // Skeptic gets Search Tools to verify claims
      const skepticRes = await this.callAgentJSON(
        modelName,
        generateSystemInstruction(skeptic, config),
        SKEPTIC_PROMPT(debateTranscript, currentDraft),
        SKEPTIC_SCHEMA,
        {
            useTools: true,
            temperature: skeptic.temperature,
            topK: skeptic.topK,
            topP: skeptic.topP
        }
      );

      debateTranscript += `\n[${skeptic.name}]: ${skepticRes.data.analysis}\nFlaws: ${skepticRes.data.flaws.join(", ")}\n`;

      const skepticLogContent = skepticRes.data.has_flaws 
        ? `OBJECTION: ${skepticRes.data.analysis}`
        : `AGREEMENT: ${skepticRes.data.analysis}`;

      onLog(this.createLog(
        'skeptic', 
        skeptic.name, 
        skepticLogContent, 
        false, 
        skepticRes.data,
        skepticRes.sources // Log Skeptic's verification sources
      ));

      if (!skepticRes.data.has_flaws) {
        consensus = true;
        break;
      }

      if (i === config.max_rounds) break;

      // ANALYST REBUTTAL
      onLog(this.createLog('analyst', analyst.name, "Processing critique & refining...", true));

      const rebuttalRes = await this.callAgentJSON(
        modelName,
        generateSystemInstruction(analyst, config),
        `CRITIQUE RECEIVED: ${skepticRes.data.analysis}\nSUGGESTED CORRECTION: ${skepticRes.data.correction}\n\nRefine your answer.`,
        ANALYST_SCHEMA,
        {
            useTools: true,
            temperature: analyst.temperature,
            topK: analyst.topK,
            topP: analyst.topP
        }
      );

      currentDraft = rebuttalRes.data.factual_answer;
      debateTranscript += `\n[${analyst.name} (Refined)]: ${currentDraft}\n`;
      onLog(this.createLog(
        'analyst', 
        analyst.name, 
        currentDraft, 
        false, 
        rebuttalRes.data,
        rebuttalRes.sources
      ));
    }

    // --- JUDGE ---
    onLog(this.createLog('judge', judge.name, "Compiling final verdict...", true));

    // Passing the turn counter (roundsExecuted) to the Judge Prompt for Fallback Logic
    const judgeRes = await this.callAgentJSON(
      modelName,
      generateSystemInstruction(judge, config),
      JUDGE_PROMPT(debateTranscript, consensus, roundsExecuted),
      JUDGE_SCHEMA,
      {
          useTools: false,
          temperature: judge.temperature,
          topK: judge.topK,
          topP: judge.topP
      }
    );

    onLog(this.createLog(
      'judge', 
      judge.name, 
      judgeRes.data.final_verdict, 
      false, 
      judgeRes.data
    ));

    return judgeRes.data.final_verdict;
  }

  private createLog(
    role: any, 
    name: string, 
    content: string, 
    isThinking: boolean, 
    metadata?: any, 
    sources?: any[]
  ): LogEntry {
    return {
      id: uuid(),
      agentRole: role,
      agentName: name,
      content,
      isThinking,
      timestamp: Date.now(),
      metadata,
      sources
    };
  }
}

import React, { useState, useEffect, useCallback } from 'react';
import { AgentCard } from './features/reasoning/components/AgentCard';
import { ReasoningLog } from './features/reasoning/components/ReasoningLog';
import { ConfigEditor } from './features/reasoning/components/ConfigEditor';
import { BootSequence } from './components/BootSequence';
import { DEFAULT_CONFIG, PRESETS } from './features/reasoning/constants';
import { SystemConfig, ProcessState } from './features/reasoning/types';
import { useReasoningEngine } from './features/reasoning/hooks/useReasoningEngine';
import { useSoundFX } from './features/reasoning/hooks/useSoundFX';

const CONFIG_STORAGE_KEY = 'veritas_system_config';

const App: React.FC = () => {
  // App State
  const [isBooting, setIsBooting] = useState(true);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Sound Engine
  const { playBlip, playClick, playActivate, playDataStream, playVerdict, playError, isMuted, toggleMute } = useSoundFX();

  // Load config
  const [config, setConfig] = useState<SystemConfig>(() => {
    try {
      const saved = localStorage.getItem(CONFIG_STORAGE_KEY);
      return saved ? JSON.parse(saved) : DEFAULT_CONFIG;
    } catch (e) {
      return DEFAULT_CONFIG;
    }
  });

  const [activePreset, setActivePreset] = useState<string>('DEFAULT');
  const [isEditingConfig, setIsEditingConfig] = useState(false);
  const [userPrompt, setUserPrompt] = useState('');

  const { logs, processState, finalResult, currentRound, chatHistory, startReasoning, clearMemory } = useReasoningEngine(config);

  // Audio Triggers based on State
  useEffect(() => {
    if (isBooting) return;
    if (processState === ProcessState.ANALYZING) playActivate();
    if (processState === ProcessState.AUDITING) playDataStream();
    if (processState === ProcessState.COMPLETE) playVerdict();
    if (processState === ProcessState.ERROR) playError();
  }, [processState, playActivate, playDataStream, playVerdict, playError, isBooting]);

  // Audio Trigger on new logs
  useEffect(() => {
    if (isBooting) return;
    if (logs.length > 0) {
        playBlip();
    }
  }, [logs.length, playBlip, isBooting]);

  // Global Keyboard Shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        if (e.metaKey || e.ctrlKey) {
            if (e.key === 'k') {
                e.preventDefault();
                playClick();
                clearMemory();
            }
            if (e.key === 'Enter') {
                // If focus is not in textarea, do nothing or focus it
            }
        }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [clearMemory, playClick]);

  const handleSaveConfig = (newConfig: SystemConfig) => {
    setConfig(newConfig);
    localStorage.setItem(CONFIG_STORAGE_KEY, JSON.stringify(newConfig));
    setIsEditingConfig(false);
    setActivePreset('CUSTOM');
    playVerdict();
  };

  const handlePresetChange = (key: string) => {
      playClick();
      setActivePreset(key);
      setConfig(PRESETS[key]);
  };

  const handleExecute = () => {
    if (userPrompt.trim()) {
        playActivate();
        startReasoning(userPrompt);
        setUserPrompt(''); // Clear input on send
        if (window.innerWidth < 768) {
          setIsSidebarOpen(false); // Close sidebar on mobile on execute
        }
    }
  };

  const handleExport = () => {
    playClick();
    const dataStr = JSON.stringify(logs, null, 2);
    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `veritas_transcript_${Date.now()}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleInterrogate = (agentName: string) => {
      playClick();
      setUserPrompt(`@${agentName}: `);
      const textarea = document.querySelector('textarea');
      if (textarea) textarea.focus();
      if (window.innerWidth < 768) setIsSidebarOpen(false);
  };

  const isProcessing = processState !== ProcessState.IDLE && processState !== ProcessState.COMPLETE && processState !== ProcessState.ERROR;

  if (isBooting) {
    return <BootSequence onComplete={() => setIsBooting(false)} />;
  }

  return (
    <div className="h-screen w-screen bg-veritas-black text-white font-sans selection:bg-veritas-cyan selection:text-black flex flex-col overflow-hidden crt-flicker">

      {/* HEADER */}
      <header className="h-14 border-b border-zinc-800 bg-black flex justify-between items-center px-4 md:px-6 relative z-50">
        <div className="flex items-center gap-4">
           {/* Mobile Menu Toggle */}
           <button 
             className="md:hidden text-veritas-cyan"
             onClick={() => setIsSidebarOpen(!isSidebarOpen)}
           >
             ☰
           </button>

          <div className="flex items-center gap-2 md:gap-4">
            <div className="w-6 h-6 bg-veritas-cyan flex items-center justify-center cursor-pointer hover:opacity-80 transition-opacity" onClick={playVerdict}>
              <span className="text-black font-bold text-xs">V</span>
            </div>
            <div className="flex flex-col">
              <h1 className="text-sm md:text-lg font-bold tracking-[0.2em] text-white leading-none">VERITAS</h1>
              <span className="hidden md:inline text-[9px] text-zinc-500 font-mono tracking-widest">MULTI-AGENT TRUTH ENGINE</span>
            </div>
          </div>

          {/* PRESET SELECTOR */}
          <div className="hidden lg:flex ml-8 bg-zinc-900 rounded-sm border border-zinc-800 p-0.5">
             {Object.keys(PRESETS).map(key => (
                 <button
                    key={key}
                    onClick={() => handlePresetChange(key)}
                    className={`px-3 py-1 text-[9px] font-mono tracking-wider transition-all ${activePreset === key ? 'bg-veritas-cyan text-black font-bold' : 'text-zinc-500 hover:text-white'}`}
                 >
                    {key}
                 </button>
             ))}
             {activePreset === 'CUSTOM' && (
                 <span className="px-3 py-1 text-[9px] font-mono tracking-wider bg-zinc-800 text-zinc-300">CUSTOM</span>
             )}
          </div>
        </div>

        {/* CENTER STATUS - CYCLE INDICATOR */}
        {isProcessing && currentRound > 0 && (
          <div className="hidden lg:flex flex-col items-center justify-center absolute left-1/2 transform -translate-x-1/2">
             <div className="flex items-center gap-1 mb-1">
               <span className="text-[9px] text-veritas-gold font-mono tracking-widest animate-pulse">RECURSIVE CYCLE {currentRound} / {config.max_rounds}</span>
             </div>
             <div className="flex gap-1">
                {[...Array(config.max_rounds)].map((_, i) => (
                  <div 
                    key={i} 
                    className={`h-1 w-8 rounded-full transition-colors duration-500 ${i < currentRound ? 'bg-veritas-gold' : 'bg-zinc-800'}`}
                  ></div>
                ))}
             </div>
          </div>
        )}

        <div className="flex items-center gap-2 md:gap-6">
          <div className="hidden md:flex items-center gap-2">
            <span className={`w-2 h-2 rounded-full ${isProcessing ? 'bg-veritas-red animate-pulse' : 'bg-zinc-700'}`}></span>
            <span className="text-[10px] font-mono text-zinc-400">STATUS: {processState}</span>
          </div>
          <div className="flex gap-2">
            {/* Audio Toggle */}
             <button 
              onClick={toggleMute}
              className={`text-[10px] font-mono border border-zinc-800 px-3 py-1 hover:bg-zinc-900 transition-colors uppercase ${isMuted ? 'text-zinc-600 line-through' : 'text-veritas-cyan'}`}
              title={isMuted ? "Unmute Sound" : "Mute Sound"}
            >
              {isMuted ? 'MUTE' : 'AUDIO'}
            </button>

             <button 
              onClick={handleExport}
              className="hidden md:block text-[10px] font-mono text-zinc-400 border border-zinc-800 px-3 py-1 hover:bg-zinc-900 transition-colors uppercase"
              title="Export Transcript JSON (Ctrl+E)"
            >
              EXP
            </button>
            <button 
              onClick={() => { playClick(); clearMemory(); }}
              className="text-[10px] font-mono text-zinc-400 border border-zinc-800 px-3 py-1 hover:bg-zinc-900 hover:text-veritas-red transition-colors uppercase"
              title="Reset Memory & Logs (Ctrl+K)"
            >
              RST
            </button>
            <button 
              onClick={() => { playClick(); setIsEditingConfig(true); }}
              className="text-[10px] font-mono text-veritas-cyan border border-veritas-cyan/30 px-3 py-1 hover:bg-veritas-cyan/10 transition-colors uppercase"
            >
              CFG
            </button>
          </div>
        </div>
      </header>

      {/* MAIN CONTENT */}
      <main className="flex-1 flex overflow-hidden relative">
        <div className="absolute inset-0 bg-grid-pattern opacity-10 pointer-events-none"></div>

        {/* SIDEBAR (Desktop: Fixed / Mobile: Absolute Overlay) */}
        <aside className={`
            fixed inset-y-0 left-0 z-30 w-80 bg-black/95 backdrop-blur-md border-r border-zinc-800 transform transition-transform duration-300
            md:relative md:translate-x-0 md:bg-black/50 md:backdrop-blur-sm md:flex md:flex-col
            ${isSidebarOpen ? 'translate-x-0 pt-14 md:pt-0' : '-translate-x-full'}
        `}>
          <div className="p-4 border-b border-zinc-800 bg-zinc-900/50 flex justify-between items-center">
            <h2 className="text-[10px] font-mono text-zinc-500 uppercase tracking-widest mb-1">Active Neural Nodes</h2>
            <button onClick={() => setIsSidebarOpen(false)} className="md:hidden text-zinc-500">✕</button>
          </div>
          <div className="flex-1 p-4 space-y-4 overflow-y-auto">
             {config.agents.map((agent) => (
               <AgentCard 
                    key={agent.role} 
                    config={agent} 
                    currentState={processState} 
                    onInterrogate={handleInterrogate}
                />
             ))}
          </div>

          {/* Mobile Preset Selector (since header hides it) */}
          <div className="md:hidden p-4 border-t border-zinc-800">
             <div className="flex flex-wrap gap-2">
                 {Object.keys(PRESETS).map(key => (
                     <button
                        key={key}
                        onClick={() => { handlePresetChange(key); setIsSidebarOpen(false); }}
                        className={`px-3 py-1 text-[9px] font-mono tracking-wider border border-zinc-800 ${activePreset === key ? 'bg-veritas-cyan text-black font-bold' : 'text-zinc-500'}`}
                     >
                        {key}
                     </button>
                 ))}
             </div>
          </div>
        </aside>

        {/* CENTER DASHBOARD */}
        <section className="flex-1 flex flex-col min-w-0 bg-black/20 relative z-10">
          <div className="flex-1 relative border-b border-zinc-800 overflow-hidden flex flex-col">
             <ReasoningLog logs={logs} agents={config.agents} />
          </div>

          {/* INPUT AREA */}
          <div className="bg-black border-t border-zinc-800 p-4 flex flex-col md:flex-row gap-4 items-center shrink-0">
             <div className="flex-1 relative w-full h-24 md:h-24">
               <textarea 
                 value={userPrompt}
                 onChange={(e) => setUserPrompt(e.target.value)}
                 onKeyDown={(e) => {
                    if (e.key === 'Enter' && !e.shiftKey) {
                        e.preventDefault();
                        if (!isProcessing) handleExecute();
                    }
                 }}
                 placeholder={
                    isProcessing ? "PROCESSING STREAM..." : 
                    chatHistory.length > 0 ? "ENTER FOLLOW-UP QUERY OR NEW TOPIC..." : 
                    "INPUT QUERY FOR VERIFICATION..."
                 }
                 disabled={isProcessing}
                 className="w-full h-full bg-zinc-900/50 border border-zinc-800 text-veritas-cyan font-mono text-sm p-3 focus:outline-none focus:border-veritas-cyan/50 resize-none placeholder:text-zinc-700 disabled:opacity-50"
               />
               <div className="absolute top-0 right-0 p-1">
                 <div className="w-2 h-2 border border-zinc-600"></div>
               </div>
             </div>

             <div className="flex flex-col gap-2 w-full md:w-auto">
                 <button
                    onClick={handleExecute}
                    disabled={isProcessing || !userPrompt.trim()}
                    className="w-full h-12 md:h-16 px-8 bg-veritas-cyan/10 border border-veritas-cyan text-veritas-cyan font-mono font-bold tracking-wider hover:bg-veritas-cyan hover:text-black transition-all disabled:opacity-30 disabled:cursor-not-allowed"
                 >
                    {isProcessing ? 'PROCESSING' : 'EXECUTE'}
                 </button>
                 {chatHistory.length > 0 && !isProcessing && (
                   <button
                        onClick={() => { playClick(); clearMemory(); }}
                        className="w-full text-[9px] text-zinc-500 hover:text-veritas-red border border-transparent hover:border-zinc-800 py-1 transition-colors uppercase tracking-widest"
                    >
                        CLEAR CONTEXT
                    </button>
                 )}
             </div>
          </div>
        </section>
      </main>

      {/* MODAL */}
      {isEditingConfig && (
        <ConfigEditor config={config} onSave={handleSaveConfig} onClose={() => setIsEditingConfig(false)} />
      )}

      {/* Overlay for mobile sidebar background */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/50 z-20 md:hidden backdrop-blur-sm"
          onClick={() => setIsSidebarOpen(false)}
        ></div>
      )}
    </div>
  );
};

